/* Balance MINUS bhi ho sakta hai — jitna wapas kiya gaya wo jitna liya gaya
   us se zyada ho to (2000 liya, 3000 wapas kiya → −1000). Pehle yahan
   Math.max(0, …) laga tha jo har negative ko 0 bana deta tha, is liye Net
   Payable/Receivable me wo −1000 kabhi nazar hi nahi aata tha. */
function bookCalc(b) {
  /* List view loads books without their ledger; trust the server's
     aggregate totals so cards & stats are correct without the entries. */
  if ((!b.txns || b.txns.length === 0) && b.serverBalance != null) {
    const received = Number(b.serverReceived || 0);
    const returned = Number(b.serverReturned || 0);
    return {
      received,
      returned,
      adjust: 0,
      balance: Number(b.serverBalance || 0),
      totalIn: received,
      returnedAll: returned,
      withBal: [],
      lastDate: b.openDate
    };
  }
  let received = 0,
    returned = 0,
    adjust = 0;
  const sorted = [...(b.txns || [])].sort((a, c) => a.date < c.date ? -1 : a.date > c.date ? 1 : (a.at || '') < (c.at || '') ? -1 : 1);
  let bal = Number(b.opening || 0);
  const withBal = sorted.map(t => {
    const amt = Number(t.amount || 0);
    if (t.type === 'received') {
      received += amt;
      bal += amt;
    } else if (t.type === 'returned') {
      returned += amt;
      bal -= amt;
    } else {
      adjust += amt;
      bal += amt;
    }
    return {
      ...t,
      runningBalance: bal
    };
  });
  return {
    received,
    returned,
    adjust,
    balance: bal,
    totalIn: received,
    returnedAll: returned,
    withBal,
    lastDate: sorted.length ? sorted[sorted.length - 1].date : b.openDate
  };
}

