];
const finTypeMeta = (key) => ACC_FIN_TYPES.find(t => t.key === key) || ACC_FIN_TYPES[3];
const todayISO = () => new Date().toISOString().slice(0, 10);

function AccountsManagementTab({ toast }) {
  // const { data: serverTxns = ACC_EMPTY_TXNS } = useAsync(accountsService.getAccTxns, ACC_EMPTY_TXNS);
  const { data: serverTxns = ACC_EMPTY_TXNS } = useAsync(accountsService.getAccTxns, ACC_EMPTY_TXNS);
  const school = useBranchSchool();
  /* Wallets + transfers come from the Chain-Management API (networkID null,
     current branch). null = still loading; [] = loaded, nothing there. */
  const [accounts, setAccounts] = useState(null);
  const [transfers, setTransfers] = useState(null);
  const [loadError, setLoadError] = useState('');

  const reloadAccounts = useCallback(async () => {
    const rows = await accountsService.getFinAccounts();
    setAccounts(rows);
    return rows;
  }, []);
  const reloadTransfers = useCallback(async () => {
    const rows = await accountsService.getTransfers();
    setTransfers(rows);
    return rows;
  }, []);

  useEffect(() => {
    let cancelled = false;
    setLoadError('');
    Promise.all([accountsService.getFinAccounts(), accountsService.getTransfers()])
      .then(([accs, trs]) => { if (!cancelled) { setAccounts(accs); setTransfers(trs); } })
      .catch((e) => {
        if (cancelled) return;
        setAccounts([]); setTransfers([]);
        setLoadError(e?.message || 'Could not load wallets');
      });
    return () => { cancelled = true; };
  }, []);

  const list = accounts || [];
  const transferList = transfers || [];

  const defaultId = (list.find(a => a.isDefault) || list[0] || {}).id;
  const activeAccounts = list.filter(a => a.status === 'active');
  const balanceOf = (a) => accountsService.computeFinAccountBalance(a, serverTxns, transferList, defaultId);

  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [editAccount, setEditAccount] = useState(null); // { mode:'add'|'edit', account? }
  const [transferOpen, setTransferOpen] = useState(false);
  const [statementFor, setStatementFor] = useState(null); // account
  const [confirm, setConfirm] = useState(null);

  const filtered = list.filter(a => {
    const q = search.trim().toLowerCase();
    const matchQ = !q || a.name.toLowerCase().includes(q) || (a.bankName || '').toLowerCase().includes(q) || (a.accountNo || '').includes(q) || finTypeMeta(a.type).label.toLowerCase().includes(q);
    if (!matchQ) return false;
   if (statusFilter !== 'all' && a.status !== statusFilter) return false;
    return true;
  }).sort((a, b) => {
    if (!!a.isDefault !== !!b.isDefault) return a.isDefault ? -1 : 1;
    if ((a.status === 'inactive') !== (b.status === 'inactive')) return a.status === 'inactive' ? 1 : -1;
    return 0;
  });

  const totalOpening= list.reduce((a, x) => a + (Number(x.opening) || 0), 0);
  const totalCurrent = list.reduce((a, x) => a + balanceOf(x), 0);
  const activeCount = list.filter(a => a.status === 'active').length;

  const saveAccount = async (payload) => {
    const isEdit = editAccount?.mode === 'edit';
    const id = isEdit ? editAccount.account.id : undefined;
    try {
      await accountsService.saveFinAccount(payload, id);
    } catch (e) {
      toast(e?.message || 'Could not save this account. Please try again.', 'error');
      return;
    }
    await reloadAccounts().catch(() => {});
    toast(isEdit ? 'Account updated' : 'Account created', 'success');
    setEditAccount(null);
  };

  const requestToggleStatus = (a) => {
    if (a.isDefault) return; // no control is ever rendered for the default account, but guard here too
    const next = a.status === 'active' ? 'inactive' : 'active';
    if (next === 'active') {
      accountsService.setFinAccountStatus({ id: a.id, status: 'active' })
        .then(() => {
          setAccounts(prev => (prev || []).map(x => (x.id === a.id ? { ...x, status: 'active' } : x)));
          toast(`${a.name} re-enabled`, 'success');
        })
        .catch((e) => toast(e?.message || 'Could not re-enable this account', 'error'));
      return;
    }
    setConfirm({
      title: 'Disable this account?',
      message: <span><strong>{a.name}</strong> will be hidden from account pickers. Its balance and history are kept, and it can be re-enabled any time.</span>,
      confirmLabel: 'Yes, Disable',
      onConfirm: async () => {
        try {
          await accountsService.setFinAccountStatus({ id: a.id, status: 'inactive' });
        } catch (e) {
          toast(e?.message || 'Could not disable this account', 'error');
          return;
        }
        setAccounts(prev => (prev || []).map(x => (x.id === a.id ? { ...x, status: 'inactive' } : x)));
        toast(`${a.name} disabled`, 'info');
      },
    });
  };

  const saveTransfer = async (payload) => {
    const src = list.find(a => a.id === payload.fromId);
    if (src && payload.amount > balanceOf(src)) {
      toast('Insufficient balance in the source account', 'error');
      return;
    }
    try {
      await accountsService.saveTransfer(payload);
    } catch (e) {
      toast(e?.message || 'Could not save this transfer. Please try again.', 'error');
      return;
    }
    /* Balances can change server-side, so refresh both lists. */
    await Promise.all([reloadTransfers(), reloadAccounts()]).catch(() => {});
    const fromName = list.find(a => a.id === payload.fromId)?.name || 'account';
    const toName = list.find(a => a.id === payload.toId)?.name || 'account';
    toast(`Transferred ${fmtMoney(payload.amount)} from ${fromName} to ${toName}`, 'success');
    setTransferOpen(false);
  };

  const requestDeleteTransfer = (t) => {
    const fromName = list.find(a => a.id === t.fromId)?.name || 'account';
    const toName = list.find(a => a.id === t.toId)?.name || 'account';
    setConfirm({
      title: 'Delete this transfer?',
      message: <span>The transfer of <strong>{fmtMoney(t.amount)}</strong> from <strong>{fromName}</strong> to <strong>{toName}</strong> will be removed. Both balances will recalculate.</span>,
      hint: 'This action cannot be undone.',
      onConfirm: async () => {
        try {
          await accountsService.deleteTransfer({ id: t.id });
        } catch (e) {
          toast(e?.message || 'Could not delete this transfer', 'error');
          return;
        }
        await Promise.all([reloadTransfers(), reloadAccounts()]).catch(() => {});
        toast('Transfer deleted', 'success');
      },
    });
  };

  return (
    <>
      <div className="acc-overview">
        <div className="acc-overview-main">
          <div className="acc-overview-icon" style={{ background: 'linear-gradient(135deg,#0891B2,#0E7490)' }}><i className="fa-solid fa-wallet"></i></div>
          <div className="acc-overview-text">
            <div className="acc-overview-title">Wallets <span className="acc-books-tagchip" style={{ background: 'rgba(8,145,178,.1)', color: '#0E7490', borderColor: 'rgba(8,145,178,.25)' }}>Cash, Bank &amp; Owner Accounts</span></div>
            <div className="acc-overview-sub">Manage every place the school holds money. This includes <strong>Cash In Hand, bank accounts, and owner or custom wallets</strong>. Move balances between accounts, choose where each income lands and each expense is paid from, and view a full bank-style statement per account. <strong>Transfers move balances only. They never affect Profit &amp; Loss.</strong></div>
          </div>
        </div>
        <div className="acc-overview-stats">
          <div className="acc-ov-stat"><div className="acc-ov-stat-ic all"><i className="fa-solid fa-layer-group"></i></div><div><div className="acc-ov-stat-val">{list.length}</div><div className="acc-ov-stat-lbl">Accounts &middot; {activeCount} active</div></div></div>
          <div className="acc-ov-stat"><div className="acc-ov-stat-ic" style={{ background: 'linear-gradient(135deg,#7C3AED,#6D28D9)' }}><i className="fa-solid fa-flag"></i></div><div><div className="acc-ov-stat-val">{fmtMoney(totalOpening)}</div><div className="acc-ov-stat-lbl">Total Opening</div></div></div>
          <div className="acc-ov-stat"><div className="acc-ov-stat-ic" style={{ background: 'linear-gradient(135deg,#0891B2,#0E7490)' }}><i className="fa-solid fa-wallet"></i></div><div><div className="acc-ov-stat-val">{fmtMoney(totalCurrent)}</div><div className="acc-ov-stat-lbl">Total Available</div></div></div>
        </div>
      </div>

      <div className="fee-section fee-section--overflow">
        <div className="fee-section-body">
          <div className="fee-filters">
            <div className="fee-field fee-field--grow">
              <span className="fee-label">Search Accounts</span>
              <div className="fee-search-box">
                <i className="fa-solid fa-magnifying-glass"></i>
                <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search by account name, bank or type" />
              </div>
            </div>
            <div className="fee-field">
              <span className="fee-label">Status</span>
              <div className="fee-select-wrap">
                <select className="fee-select" value={statusFilter} onChange={e => setStatusFilter(e.target.value)}>
                  <option value="all">All Accounts</option>
                  <option value="active">Active</option>
                  <option value="inactive">Disabled</option>
                </select>
                <i className="fa-solid fa-chevron-down"></i>
              </div>
            </div>
            <Tooltip text="Move money between two of your own accounts">
              <button className="fee-btn fee-btn-ghost" onClick={() => setTransferOpen(true)} disabled={activeAccounts.length < 2} style={{ borderColor: 'rgba(8,145,178,.4)', color: '#0E7490' }}>
                <i className="fa-solid fa-right-left"></i> Transfer Money
              </button>
            </Tooltip>
            <Tooltip text="Add a new cash, bank, owner or other account">
              <button className="fee-btn fee-btn-primary" onClick={() => setEditAccount({ mode: 'add' })}>
                <i className="fa-solid fa-plus"></i> Create Account
              </button>
            </Tooltip>
          </div>
        </div>
      </div>

      {loadError && (
        <div className="acc-ledger-empty" style={{ color: 'var(--error)' }}>
          <i className="fa-solid fa-triangle-exclamation"></i>
          {loadError}
        </div>
      )}
      {accounts == null ? (
        <div className="acc-ledger-empty">
          <i className="fa-solid fa-spinner fa-spin"></i>
          Loading accounts…
        </div>
      ) : filtered.length === 0 ? (
        <div className="acc-ledger-empty">
          <i className="fa-solid fa-wallet"></i>
          No accounts found.<br/>
          Use <strong>Create Account</strong> to add one.
        </div>
      ) : (
        <div className="acc-books-grid">
          {filtered.map(a => {
            const tm = finTypeMeta(a.type);
            const bal = balanceOf(a);
            const sub = a.type === 'bank' && (a.bankName || a.accountNo)
              ? `${a.bankName || 'Bank'}${a.accountNo ? ` · ${a.accountNo}` : ''}`
              : (a.description || `${tm.label} account`);
            return (
              <div className={`acc-wallet-card${a.status === 'inactive' ? ' inactive' : ''}`} key={a.id}>
                <div className="acc-wallet-card-top">
                  <div className={`acc-wallet-ic ${a.type}`}><i className={`fa-solid ${tm.icon}`}></i></div>
                  <div className="acc-wallet-tt">
                    <div className="acc-wallet-name">
                      {a.name}
                      {a.isDefault && <span className="acc-default-chip"><i className="fa-solid fa-star"></i> Default</span>}
                    </div>
                    <div className="acc-wallet-sub">
                      <span className={`acc-type-badge ${a.type}`}><i className={`fa-solid ${tm.icon}`}></i> {tm.label}</span>
                      <span className={`acc-book-status ${a.status === 'active' ? 'active' : 'closed'}`}>{a.status === 'active' ? 'Active' : 'Disabled'}</span>
                    </div>
                  </div>
                </div>

                <div className="acc-wallet-body">
                  <div className="acc-wallet-balrow">
                    <div className="acc-wallet-bal">
                      <div className="acc-wallet-bal-lbl">Opening</div>
                      <div className="acc-wallet-bal-val">{fmtMoney(a.opening)}</div>
                    </div>
                    <div className="acc-wallet-bal current">
                      <div className="acc-wallet-bal-lbl">Current Balance</div>
                      <div className="acc-wallet-bal-val">{fmtMoney(bal)}</div>
                    </div>
                  </div>
                  <div style={{ marginTop: 11, fontSize: 11.5, color: 'var(--text-muted)', lineHeight: 1.5 }}>{sub}</div>
                </div>

                <div className="acc-wallet-foot">
                  <Tooltip text={`View ${a.name}'s statement`}>
                    <button className="fee-iconbtn acc-wallet-stmtbtn" onClick={() => setStatementFor(a)}>
                      <i className="fa-solid fa-file-invoice-dollar"></i> View Statement
                    </button>
                  </Tooltip>
                  <Tooltip text="Edit this account">
                    <button className="fee-iconbtn" onClick={() => setEditAccount({ mode: 'edit', account: a })}>
                      <i className="fa-solid fa-pen"></i>
                    </button>
                  </Tooltip>
                  {!a.isDefault && (
                    <Tooltip text={a.status === 'active' ? 'Disable this account' : 'Re-enable this account'}>
                      <button
                        className={`fee-iconbtn${a.status === 'active' ? ' danger' : ''}`}
                        onClick={() => requestToggleStatus(a)}
                      >
                        <i className={`fa-solid ${a.status === 'active' ? 'fa-ban' : 'fa-circle-check'}`}></i>
                      </button>
                    </Tooltip>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}

      <div className="fee-section fee-section--overflow" style={{ marginTop: 20 }}>
        <div className="fee-section-header">
          <div className="fee-section-title">
            <div className="fee-section-icon" style={{ background: 'linear-gradient(135deg,#0891B2,#0E7490)' }}><i className="fa-solid fa-right-left"></i></div>
            <div>
              <div className="fee-section-name">Transfer History</div>
              <div className="fee-section-sub">Money moved between accounts. Balance movement only, not income or expense.</div>
            </div>
          </div>
          <span className="fee-chip fee-chip-active"><i className="fa-solid fa-list"></i> {transferList.length}</span>
        </div>
        <div className="acc-txn-tablewrap">
          <table className="acc-txn-table">
            {transferList.length === 0 ? (
              <tbody>
                <tr><td><div className="acc-txn-empty"><i className="fa-solid fa-right-left"></i>No transfers yet.<br/>Use <strong>Transfer Money</strong> to move a balance between accounts.</div></td></tr>
              </tbody>
            ) : (
              <>
                <thead>
                  <tr>
                    <th>Date</th><th>From Account</th><th>To Account</th><th>Note</th><th className="r">Amount</th><th>Entered By</th><th className="c">Action</th>
                  </tr>
                </thead>
                <tbody>
                  {[...transferList].sort((a, b) => (b.date + b.at).localeCompare(a.date + a.at)).map(t => (
                    <tr key={t.id}>
                      <td><span className="acc-txn-date">{accFmtDate(t.date)}</span></td>
                      <td><span className="acc-stmt-tag debit"><i className="fa-solid fa-arrow-up-long"></i> {list.find(a => a.id === t.fromId)?.name || '—'}</span></td>
                      <td><span className="acc-stmt-tag credit"><i className="fa-solid fa-arrow-down-long"></i> {list.find(a => a.id === t.toId)?.name || '—'}</span></td>
                      <td>
                        <div className="acc-txn-detail">{t.note || '—'}</div>
                        <div className="acc-txn-meta"><span><i className="fa-regular fa-clock"></i> {accFmtStamp(t.at)}</span></div>
                      </td>
                      <td className="r"><span className="acc-txn-amt">{fmtMoney(t.amount)}</span></td>
                      <td><span className="acc-rep-user"><i className="fa-solid fa-user-pen"></i> {t.by || '—'}</span></td>
                      <td className="c">
                        <Tooltip text="Delete this transfer">
                          <button className="fee-iconbtn danger" onClick={() => requestDeleteTransfer(t)}>
                            <i className="fa-solid fa-trash-can"></i>
                          </button>
                        </Tooltip>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </>
            )}
          </table>
        </div>
      </div>

      <FinAccountModal cfg={editAccount} onClose={() => setEditAccount(null)} onSave={saveAccount} toast={toast} />
      <TransferModal
        open={transferOpen}
        accounts={activeAccounts}
        balanceOf={balanceOf}
        onClose={() => setTransferOpen(false)}
        onSave={saveTransfer}
        toast={toast}
      />
      <FinAccountStatementModal
        school={school}
        account={statementFor}
        accounts={list}
        txns={serverTxns}
        transfers={transferList}
        defaultId={defaultId}
        onClose={() => setStatementFor(null)}
      />
      <AccConfirmDialog cfg={confirm} onClose={() => setConfirm(null)} />
    </>
  );
}

/* ── Create / Edit Financial Account modal ── */
function FinAccountModal({ cfg, onClose, onSave, toast }) {
  const [name, setName] = useState('');
  const [type, setType] = useState('cash');
  const [opening, setOpening] = useState('');
  const [status, setStatus] = useState('active');
  const [bankName, setBankName] = useState('');
  const [accountNo, setAccountNo] = useState('');
  const [description, setDescription] = useState('');

  const isEdit = cfg?.mode === 'edit';
  const isDefault = !!cfg?.account?.isDefault;

  useEffect(() => {
    if (!cfg) return;
    if (isEdit && cfg.account) {
      const a = cfg.account;
      setName(a.name); setType(a.type); setOpening(String(a.opening ?? ''));
      setStatus(a.status); setBankName(a.bankName || ''); setAccountNo(a.accountNo || '');
      setDescription(a.description || '');
    } else {
      setName(''); setType('cash'); setOpening('0'); setStatus('active');
      setBankName(''); setAccountNo(''); setDescription('');
    }
  }, [cfg, isEdit]);

  useEffect(() => {
    if (!cfg) return undefined;
    const onKey = e => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', onKey);
    document.body.style.overflow = 'hidden';
    return () => { window.removeEventListener('keydown', onKey); document.body.style.overflow = ''; };
  }, [cfg, onClose]);

  if (!cfg) return null;

  const showBank = type === 'bank';
  const showAccountNo = type === 'bank' || type === 'other';

  const handleSubmit = () => {
    if (!name.trim()) { toast('Please enter an account name', 'error'); return; }
    onSave({
      name: name.trim(), type, opening: Number(opening) || 0,
      status: isDefault ? 'active' : status,
      bankName: showBank ? bankName.trim() : '',
      accountNo: showAccountNo ? accountNo.trim() : '',
      description: description.trim(),
    });
  };

  return createPortal(
    <div className="fee-overlay open" onClick={e => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="fee-modal">
        <div className="fee-modal-head">
          <div className="fee-modal-head-title">
            <div className="fee-modal-head-icon" style={{ background: 'linear-gradient(135deg,#0891B2,#0E7490)' }}><i className={`fa-solid ${isEdit ? 'fa-pen-to-square' : 'fa-wallet'}`}></i></div>
            <div>
              <div className="fee-modal-title">{isEdit ? 'Edit Account' : 'Create Account'}</div>
              <div className="fee-modal-sub">{isEdit ? cfg?.account?.name : 'Add a cash, bank, owner or custom financial account'}</div>
            </div>
          </div>
          <Tooltip text="Close">
            <button className="fee-modal-close" onClick={onClose} aria-label="Close"><i className="fa-solid fa-xmark"></i></button>
          </Tooltip>
        </div>

        <div className="fee-modal-body">
          <div className="fee-info" style={{ background: 'rgba(8,145,178,.06)', borderColor: 'rgba(8,145,178,.2)' }}>
            <i className="fa-solid fa-circle-info" style={{ color: '#0E7490' }}></i>
            <span>An account is a wallet where the school holds money. This includes <strong>Cash In Hand, a bank account, the owner&apos;s account</strong> or any custom location. Income can be received into it and expenses paid from it.</span>
          </div>
          <div className="acc-form-grid">
            <div className="fee-field">
              <span className="fee-label">Account Name <span className="acc-req">*</span></span>
              <input className="fee-input" value={name} onChange={e => setName(e.target.value)} placeholder="e.g. Bank of Punjab" />
            </div>
            <div className="fee-field">
              <span className="fee-label">Account Type <span className="acc-req">*</span></span>
              <div className="fee-select-wrap">
                <select className="fee-select" value={type} onChange={e => setType(e.target.value)}>
                  {ACC_FIN_TYPES.map(t => <option key={t.key} value={t.key}>{t.label}</option>)}
                </select>
                <i className="fa-solid fa-chevron-down"></i>
              </div>
            </div>
            <div className="fee-field">
              <span className="fee-label">Opening Balance</span>
              <input className="fee-input" type="number" value={opening} onChange={e => setOpening(e.target.value)} placeholder="0" />
            </div>
            <div className="fee-field">
              <span className="fee-label">Status</span>
              <div className="fee-select-wrap">
                <select className="fee-select" value={status} onChange={e => setStatus(e.target.value)} disabled={isDefault}>
                  <option value="active">Active</option>
                  <option value="inactive">Disabled</option>
                </select>
                <i className="fa-solid fa-chevron-down"></i>
              </div>
            </div>
            {showBank && (
              <div className="fee-field">
                <span className="fee-label">Bank Name <span className="acc-opt">(optional)</span></span>
                <input className="fee-input" value={bankName} onChange={e => setBankName(e.target.value)} placeholder="e.g. Bank Alfalah" />
              </div>
            )}
            {showAccountNo && (
              <div className="fee-field">
                <span className="fee-label">Account Number <span className="acc-opt">(optional)</span></span>
                <input className="fee-input" value={accountNo} onChange={e => setAccountNo(e.target.value)} placeholder="e.g. PK00-XXXX-0000-0000" />
              </div>
            )}
            <div className="fee-field" style={{ gridColumn: '1/-1' }}>
              <span className="fee-label">Description</span>
              <textarea className="fee-input fee-textarea" value={description} onChange={e => setDescription(e.target.value)} placeholder="Short description of this account" />
            </div>
          </div>

          {isDefault && (
            <div className="acc-audit-note" style={{ marginTop: 14 }}>
              <i className="fa-solid fa-star"></i>
              <div>This is the <b>default receiving account</b>. It always stays active and receives income unless another account is chosen.</div>
            </div>
          )}
        </div>

        <div className="fee-modal-foot">
          <Tooltip text="Discard changes and close"><button className="fee-btn fee-btn-ghost" onClick={onClose}>Cancel</button></Tooltip>
          <Tooltip text="Save this account">
            <button className="fee-btn fee-btn-primary" onClick={handleSubmit}><i className="fa-solid fa-floppy-disk"></i> {isEdit ? 'Save Changes' : 'Save Account'}</button>
          </Tooltip>
        </div>
      </div>
    </div>,
    document.body
  );
}

/* ── Transfer Money modal ── */
function TransferModal({ open, accounts, balanceOf, onClose, onSave, toast }) {
  const [fromId, setFromId] = useState('');
  const [toId, setToId] = useState('');
  const [amount, setAmount] = useState('');
  const [date, setDate] = useState(todayISO());
  const [note, setNote] = useState('');
  const [by, setBy] = useState('');
  const { data: users = [] } = useAsync(accountsService.getAccUsers, []);
  const { data: currentUser = '' } = useAsync(accountsService.getAccCurrentUser, '');

  useEffect(() => {
    if (!open) return;
    setFromId(accounts[0]?.id || '');
    setToId(accounts[1]?.id || accounts[0]?.id || '');
    setAmount(''); setDate(todayISO()); setNote(''); setBy(currentUser || '');
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, currentUser]);

  useEffect(() => {
    if (!open) return undefined;
    const onKey = e => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', onKey);
    document.body.style.overflow = 'hidden';
    return () => { window.removeEventListener('keydown', onKey); document.body.style.overflow = ''; };
  }, [open, onClose]);

  if (!open) return null;

  const fromAcct = accounts.find(a => a.id === fromId);
  const toAcct = accounts.find(a => a.id === toId);
  const fromBal = fromAcct ? balanceOf(fromAcct) : 0;
  const toBal = toAcct ? balanceOf(toAcct) : 0;
  const amt = Number(amount) || 0;
  const sameAccount = !!fromId && fromId === toId;
  const overdraft = amt > 0 && fromBal - amt < 0;

  const handleSubmit = () => {
    if (!fromId || !toId) { toast('Please choose both accounts', 'error'); return; }
    if (fromId === toId) { toast('Source and destination must be different', 'error'); return; }
     if (!amt || amt <= 0) { toast('Please enter a valid amount', 'error'); return; }
    if (amt > fromBal) { toast(`Insufficient balance. ${fromAcct?.name} has only ${fmtMoney(fromBal)} available.`, 'error'); return; }
    onSave({ fromId, toId, amount: amt, date, note: note.trim(), by: by || currentUser || 'You' });
  };

  return createPortal(
    <div className="fee-overlay open" onClick={e => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="fee-modal">
        <div className="fee-modal-head">
          <div className="fee-modal-head-title">
            <div className="fee-modal-head-icon" style={{ background: 'linear-gradient(135deg,#0891B2,#0E7490)' }}><i className="fa-solid fa-right-left"></i></div>
            <div>
              <div className="fee-modal-title">Transfer Money</div>
              <div className="fee-modal-sub">Move a balance from one account to another</div>
            </div>
          </div>
          <Tooltip text="Close"><button className="fee-modal-close" onClick={onClose} aria-label="Close"><i className="fa-solid fa-xmark"></i></button></Tooltip>
        </div>

        <div className="fee-modal-body">
          <div className="fee-info" style={{ background: 'rgba(8,145,178,.06)', borderColor: 'rgba(8,145,178,.2)' }}>
            <i className="fa-solid fa-circle-info" style={{ color: '#0E7490' }}></i>
            <span>A transfer moves a balance between two accounts only. The source account decreases and the destination increases. <strong>This is not income or an expense and does not affect Profit &amp; Loss.</strong></span>
          </div>

          <div className="acc-xfer-flow">
            <div className="fee-field acc-xfer-side">
              <span className="fee-label">From Account <span className="acc-req">*</span></span>
              <div className="fee-select-wrap">
                <select className="fee-select" value={fromId} onChange={e => setFromId(e.target.value)}>
                  {accounts.map(a => <option key={a.id} value={a.id}>{a.name} — {finTypeMeta(a.type).label}</option>)}
                </select>
                <i className="fa-solid fa-chevron-down"></i>
              </div>
              <div className="acc-xfer-bal"><i className="fa-solid fa-wallet"></i> Available: {fmtMoney(fromBal)}</div>
            </div>
            <div className="acc-xfer-arrow"><i className="fa-solid fa-arrow-right-long"></i></div>
            <div className="fee-field acc-xfer-side">
              <span className="fee-label">To Account <span className="acc-req">*</span></span>
              <div className="fee-select-wrap">
                <select className="fee-select" value={toId} onChange={e => setToId(e.target.value)}>
                  {accounts.map(a => <option key={a.id} value={a.id}>{a.name} — {finTypeMeta(a.type).label}</option>)}
                </select>
                <i className="fa-solid fa-chevron-down"></i>
              </div>
              <div className="acc-xfer-bal"><i className="fa-solid fa-wallet"></i> Available: {fmtMoney(toBal)}</div>
            </div>
          </div>

          <div className="acc-form-grid" style={{ marginTop: 16 }}>
            <div className="fee-field">
              <span className="fee-label">Amount <span className="acc-req">*</span></span>
              <input className="fee-input" type="number" value={amount} onChange={e => setAmount(e.target.value)} placeholder="Enter amount" />
            </div>
            <div className="fee-field">
              <span className="fee-label">Date</span>
              <input className="fee-input" type="date" value={date} onChange={e => setDate(e.target.value)} />
            </div>
            <div className="fee-field">
              <span className="fee-label">Entered By</span>
              <div className="fee-select-wrap">
                <select className="fee-select" value={by} onChange={e => setBy(e.target.value)}>
                  {users.map(u => <option key={u} value={u}>{u}</option>)}
                </select>
                <i className="fa-solid fa-chevron-down"></i>
              </div>
            </div>
            <div className="fee-field">
              <span className="fee-label">Note</span>
              <input className="fee-input" value={note} onChange={e => setNote(e.target.value)} placeholder="e.g. Deposit cash to bank" />
            </div>
          </div>

          {amt > 0 && fromId && toId && (
            <div className={`acc-xfer-preview${sameAccount || overdraft ? ' err' : ''}`}>
              {sameAccount ? (
                <>
                  <div className="acc-xfer-preview-h"><i className="fa-solid fa-triangle-exclamation"></i> Invalid transfer</div>
                  <div className="acc-xfer-preview-row"><span className="l">Source and destination are the same account.</span></div>
                </>
              ) : (
                <>
                  <div className="acc-xfer-preview-h"><i className="fa-solid fa-eye"></i> After Transfer{overdraft ? ' · insufficient balance warning' : ''}</div>
                  <div className="acc-xfer-preview-row"><span className="l">{fromAcct?.name}</span><span className="v down">{fmtMoney(fromBal)} <i className="fa-solid fa-arrow-right"></i> {fmtMoney(fromBal - amt)}</span></div>
                  <div className="acc-xfer-preview-row"><span className="l">{toAcct?.name}</span><span className="v up">{fmtMoney(toBal)} <i className="fa-solid fa-arrow-right"></i> {fmtMoney(toBal + amt)}</span></div>
                  {overdraft && (
                    <div className="acc-xfer-preview-row"><span className="l" style={{ color: 'var(--error)' }}><i className="fa-solid fa-triangle-exclamation"></i> This exceeds the available balance. The source account will go negative.</span></div>
                  )}
                  <div className="acc-xfer-preview-row" style={{ borderTop: '1px dashed var(--border-med)', marginTop: 6, paddingTop: 8 }}><span className="l"><i className="fa-solid fa-circle-info"></i> Balance movement only. It is not counted in Profit &amp; Loss.</span></div>
                </>
              )}
            </div>
          )}
        </div>

        <div className="fee-modal-foot">
          <Tooltip text="Discard and close"><button className="fee-btn fee-btn-ghost" onClick={onClose}>Cancel</button></Tooltip>
          <Tooltip text="Move the money now">
            <button className="fee-btn fee-btn-primary" onClick={handleSubmit} disabled={sameAccount}>
              <i className="fa-solid fa-right-left"></i> Transfer
            </button>
          </Tooltip>
        </div>
      </div>
    </div>,
    document.body
  );
}

/* ── Per-account bank-style Statement, with a From/To Date filter ── */
function FinAccountStatementModal({ account, accounts, txns, transfers, defaultId, onClose, school }) {  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [filter, setFilter] = useState('all');
  const [pickerOpen, setPickerOpen] = useState(false);
  /* Ledger from manage-transactions; null = loading / not available. */
  const [walletTxns, setWalletTxns] = useState(null);

  useEffect(() => {
    if (!account) return;
    setFrom(''); setTo(''); setFilter('all');
  }, [account]);

  useEffect(() => {
    if (!account) { setWalletTxns(null); return undefined; }
    let cancelled = false;
    setWalletTxns(null);
    accountsService.getWalletTransactions(account.id)
      .then((rows) => { if (!cancelled) setWalletTxns(rows); })
      .catch(() => { if (!cancelled) setWalletTxns(null); });
    return () => { cancelled = true; };
  }, [account]);

  useEffect(() => {
    if (!account) return undefined;
    const onKey = e => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', onKey);
    document.body.style.overflow = 'hidden';
    return () => { window.removeEventListener('keydown', onKey); document.body.style.overflow = ''; };
  }, [account, onClose]);

  if (!account) return null;

  const tm = finTypeMeta(account.type);
  const current = accountsService.computeFinAccountBalance(account, txns, transfers, defaultId);
  let income = (txns?.rev || []).filter(t => (t.acctId || defaultId) === account.id).reduce((s, t) => s + (Number(t.amount) || 0), 0);
  let expense = (txns?.exp || []).filter(t => (t.acctId || defaultId) === account.id).reduce((s, t) => s + (Number(t.amount) || 0), 0);
  let transfersIn = (transfers || []).filter(t => t.toId === account.id).reduce((s, t) => s + (Number(t.amount) || 0), 0);
  let transfersOut = (transfers || []).filter(t => t.fromId === account.id).reduce((s, t) => s + (Number(t.amount) || 0), 0);

  /* Every move (revenue/expense/transfer) that touches this account,
     chronologically ordered — the same shape the reference prototype's
     statement math uses: fold the whole list for a running balance,
     then read off Brought Forward / Closing at the date boundaries. */
  const moves = [];
  /* The wallet ledger from the API is authoritative (it already includes
     transfers). Only when it has nothing do we derive moves from the day-book
     + transfers, so a transfer is never counted twice. */
  const useLedger = Array.isArray(walletTxns) && walletTxns.length > 0;
  if (useLedger) walletTxns.forEach(m => moves.push({ ...m }));
  if (!useLedger) (txns?.rev || []).forEach(t => {
    if ((t.acctId || defaultId) === account.id) moves.push({ date: t.date, desc: t.detail || t.head, ref: `Revenue · ${t.head}`, cat: 'revenue', amount: Number(t.amount) || 0, kind: 'credit' });
  });
  if (!useLedger) (txns?.exp || []).forEach(t => {
    if ((t.acctId || defaultId) === account.id) moves.push({ date: t.date, desc: t.detail || t.head, ref: `Expense · ${t.head}`, cat: 'expense', amount: Number(t.amount) || 0, kind: 'debit' });
  });
  if (!useLedger) (transfers || []).forEach(tr => {
    if (tr.toId === account.id) {
      const fromName = accounts.find(a => a.id === tr.fromId)?.name || 'another account';
      moves.push({ date: tr.date, desc: tr.note || `Transfer from ${fromName}`, ref: `Transfer from ${fromName}`, cat: 'transfer', amount: Number(tr.amount) || 0, kind: 'credit' });
    }
    if (tr.fromId === account.id) {
      const toName = accounts.find(a => a.id === tr.toId)?.name || 'another account';
      moves.push({ date: tr.date, desc: tr.note || `Transfer to ${toName}`, ref: `Transfer to ${toName}`, cat: 'transfer', amount: Number(tr.amount) || 0, kind: 'debit' });
    }
  });
  moves.sort((a, b) => a.date.localeCompare(b.date));
  if (useLedger) {
    const sum = (fn) => moves.filter(fn).reduce((a, m) => a + m.amount, 0);
    income       = sum(m => m.cat === 'revenue');
    expense      = sum(m => m.cat === 'expense');
    transfersIn  = sum(m => m.cat === 'transfer' && m.kind === 'credit');
    transfersOut = sum(m => m.cat === 'transfer' && m.kind === 'debit');
  }

   const broughtForward = from
    ? (Number(account.opening) || 0)
      + moves.filter(m => m.date < from).reduce((a, m) => a + (m.kind === 'credit' ? m.amount : -m.amount), 0)
    : (Number(account.opening) || 0);
  let rangeMoves = moves.filter(m => (!from || m.date >= from) && (!to || m.date <= to));
  if (filter !== 'all') rangeMoves = rangeMoves.filter(m => m.kind === filter);
  if (filter !== 'all') rangeMoves = rangeMoves.filter(m => m.kind === filter);
  let running = broughtForward;
  const rows = rangeMoves.map(m => {
    running += m.kind === 'credit' ? m.amount : -m.amount;
    return { ...m, balance: running };
  });
  const closing = (Number(account.opening) || 0)
    + moves.filter(m => !to || m.date <= to).reduce((a, m) => a + (m.kind === 'credit' ? m.amount : -m.amount), 0);
  const totalDebit = rangeMoves.filter(m => m.kind === 'debit').reduce((a, m) => a + m.amount, 0);
  const totalCredit = rangeMoves.filter(m => m.kind === 'credit').reduce((a, m) => a + m.amount, 0);
  const openLabel = from ? 'Balance Brought Forward' : 'Opening Balance';
  const openDate = from || String(account.createdAt || '').slice(0, 10) || '';
  const catLabel = (m) => (m.cat === 'transfer' ? 'Transfer' : (m.kind === 'credit' ? 'Credit' : 'Debit'));
  const tagFor = (m) => (m.cat === 'transfer' ? 'xfer' : (m.kind === 'credit' ? 'credit' : 'debit'));

  const buildRows = () => rows.map(r => `<tr><td>${accFmtDate(r.date)}</td><td>${escHtmlAcc(r.desc)}</td><td>${catLabel(r)}</td><td class="r">${r.kind === 'debit' ? r.amount.toLocaleString('en-PK') : ''}</td><td class="r">${r.kind === 'credit' ? r.amount.toLocaleString('en-PK') : ''}</td><td class="r">${r.balance.toLocaleString('en-PK')}</td></tr>`).join('');

  const statementFilename = `${account.name.replace(/[^A-Za-z0-9]+/g, '-')}-statement-${from || 'all'}-to-${to || 'all'}`;

  const doGenerate = (style, format) => {
    const isBW = style === 'bw';
    if (format === 'excel') {
      const csv = buildFinStatementCSV({ account, from, to, openLabel, openDate, broughtForward, rows, closing });
      const blob = new Blob([csv], { type: 'application/vnd.ms-excel' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `${statementFilename}.xls`;
      document.body.appendChild(a); a.click(); document.body.removeChild(a);
      URL.revokeObjectURL(url);
      setPickerOpen(false);
      return;
    }
    const html = buildFinStatementHTML({ account, from, to, openLabel, openDate, broughtForward, rows, closing, totalDebit, totalCredit, buildRows, isBW, school });
    if (format === 'word') {
      downloadReportAsWord(html, `${statementFilename}.doc`);
      setPickerOpen(false);
      return;
    }
    const w = window.open('', '_blank');
    if (w) {
      w.document.write(html); w.document.close();
      w.onload = () => { try { w.focus(); w.print(); } catch (e) { /* ignore */ } };
    }
    setPickerOpen(false);
  };

  return createPortal(
    <div className="fee-overlay open" onClick={e => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="fee-modal lg">
        <div className="fee-modal-head">
          <div className="fee-modal-head-title">
            <div className="fee-modal-head-icon" style={{ background: 'linear-gradient(135deg,#0891B2,#0E7490)' }}><i className={`fa-solid ${tm.icon}`}></i></div>
            <div>
              <div className="fee-modal-title">{account.name}</div>
              <div className="fee-modal-sub">Bank-style statement with running balance</div>
            </div>
          </div>
          <Tooltip text="Close"><button className="fee-modal-close" onClick={onClose} aria-label="Close"><i className="fa-solid fa-xmark"></i></button></Tooltip>
        </div>

        <div className="fee-modal-body">
          <div className="acc-book-summary">
            <div className="acc-bsum b-opening"><div className="acc-bsum-top"><span className="acc-bsum-lbl">Opening Balance</span><span className="acc-bsum-ic"><i className="fa-solid fa-flag"></i></span></div><div className="acc-bsum-val">{fmtMoney(account.opening)}</div><div className="acc-bsum-meta">{account.type === 'bank' && account.bankName ? account.bankName : `${tm.label} account`}</div></div>
            <div className="acc-bsum b-balance"><div className="acc-bsum-top"><span className="acc-bsum-lbl">Current Balance</span><span className="acc-bsum-ic"><i className="fa-solid fa-scale-balanced"></i></span></div><div className="acc-bsum-val">{fmtMoney(current)}</div><div className="acc-bsum-meta">available now</div></div>
            <div className="acc-bsum b-in"><div className="acc-bsum-top"><span className="acc-bsum-lbl">Income Received</span><span className="acc-bsum-ic"><i className="fa-solid fa-arrow-down"></i></span></div><div className="acc-bsum-val">{fmtMoney(income)}</div><div className="acc-bsum-meta">into this account</div></div>
            <div className="acc-bsum b-out"><div className="acc-bsum-top"><span className="acc-bsum-lbl">Expenses Paid</span><span className="acc-bsum-ic"><i className="fa-solid fa-arrow-up"></i></span></div><div className="acc-bsum-val">{fmtMoney(expense)}</div><div className="acc-bsum-meta">from this account</div></div>
            <div className="acc-bsum b-cash"><div className="acc-bsum-top"><span className="acc-bsum-lbl">Transfers In</span><span className="acc-bsum-ic"><i className="fa-solid fa-arrow-right-to-bracket"></i></span></div><div className="acc-bsum-val sm">{fmtMoney(transfersIn)}</div><div className="acc-bsum-meta">received via transfer</div></div>
            <div className="acc-bsum b-date"><div className="acc-bsum-top"><span className="acc-bsum-lbl">Transfers Out</span><span className="acc-bsum-ic"><i className="fa-solid fa-arrow-right-from-bracket"></i></span></div><div className="acc-bsum-val sm">{fmtMoney(transfersOut)}</div><div className="acc-bsum-meta">sent via transfer</div></div>
          </div>

          <div className="acc-ledger-toolbar">
            <div className="acc-ledger-toolbar-l">
              <div className="fee-field"><span className="fee-label" style={{ fontSize: 10 }}>From Date</span>
                <input className="fee-input fee-input-sm" type="date" value={from} onChange={e => setFrom(e.target.value)} /></div>
              <div className="fee-field"><span className="fee-label" style={{ fontSize: 10 }}>To Date</span>
                <input className="fee-input fee-input-sm" type="date" value={to} onChange={e => setTo(e.target.value)} /></div>
              <div className="fee-select-wrap" style={{ alignSelf: 'flex-end' }}>
                <select className="fee-select" value={filter} onChange={e => setFilter(e.target.value)} style={{ minWidth: 150 }}>
                  <option value="all">All Movements</option>
                  <option value="credit">Credit (In)</option>
                  <option value="debit">Debit (Out)</option>
                </select>
                <i className="fa-solid fa-chevron-down"></i>
              </div>
            </div>
            <div style={{ display: 'flex', gap: 8, alignSelf: 'flex-end' }}>
              <Tooltip text="Download this statement as PDF, Word or Excel">
                <button className="fee-btn fee-btn-ghost fee-btn-sm" onClick={() => setPickerOpen(true)}><i className="fa-solid fa-file-lines"></i> Download Report</button>
              </Tooltip>
            </div>
          </div>

<div className="acc-txn-tablewrap acc-stmt-wrap">
            <table className="acc-txn-table acc-stmt-table">
              <thead>
                <tr><th>Date</th><th>Description</th><th>Type</th><th className="r">Debit (Out)</th><th className="r">Credit (In)</th><th className="r">Balance</th></tr>
              </thead>
              <tbody>
                <tr style={{ background: 'var(--bg-muted)' }}>
                  <td><span className="acc-txn-date">{openDate ? accFmtDate(openDate) : '—'}</span></td>
                  <td className="acc-txn-headname">{openLabel}</td>
                  <td><span className="acc-stmt-tag opening"><i className="fa-solid fa-flag"></i> Opening</span></td>
                  <td className="r">—</td><td className="r">—</td>
                  <td className="r acc-stmt-bal">{fmtMoney(broughtForward)}</td>
                </tr>
                {rows.length === 0 ? (
                  <tr><td colSpan={6}><div className="acc-txn-empty"><i className="fa-solid fa-inbox"></i>No movements in this period.</div></td></tr>
                ) : rows.map((r, i) => (
                  <tr key={i}>
                    <td><span className="acc-txn-date">{accFmtDate(r.date)}</span></td>
                    <td><div className="acc-txn-detail">{r.desc || '—'}</div><div className="acc-txn-meta"><span>{r.ref}</span></div></td>
                    <td><span className={`acc-stmt-tag ${tagFor(r)}`}><i className={`fa-solid ${r.cat === 'transfer' ? 'fa-right-left' : (r.kind === 'credit' ? 'fa-arrow-down-long' : 'fa-arrow-up-long')}`}></i> {catLabel(r)}</span></td>
                    <td className={`r${r.kind === 'debit' ? ' acc-stmt-debit' : ''}`}>{r.kind === 'debit' ? fmtMoney(r.amount) : '—'}</td>
                    <td className={`r${r.kind === 'credit' ? ' acc-stmt-credit' : ''}`}>{r.kind === 'credit' ? fmtMoney(r.amount) : '—'}</td>
                    <td className="r acc-stmt-bal">{fmtMoney(r.balance)}</td>
                  </tr>
                ))}
              </tbody>
              <tfoot>
                <tr>
                  <td colSpan={3} className="acc-txn-totlbl">Period Totals:</td>
                  <td className="r acc-stmt-debit">{fmtMoney(totalDebit)}</td>
                  <td className="r acc-stmt-credit">{fmtMoney(totalCredit)}</td>
                  <td className="r acc-stmt-bal">{fmtMoney(closing)}</td>
                </tr>
              </tfoot>
            </table>
          </div>
        </div>

        <div className="fee-modal-foot">
          <Tooltip text="Close"><button className="fee-btn fee-btn-ghost" onClick={onClose}>Close</button></Tooltip>
        </div>
      </div>
      {pickerOpen && (
        <StandardReportPicker
          open
          title={`${account.name} — Statement`}
          subtitle="Choose style and format, then generate."
          formats={['pdf', 'word', 'excel']}
          onClose={() => setPickerOpen(false)}
          onGenerate={doGenerate}
        />
      )}
    </div>,
    document.body
  );
}

const escHtmlAcc = (s) => String(s ?? '').replace(/[&<>"']/g, m => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[m]));

function buildFinStatementHTML({ account, from, to, openLabel, openDate, broughtForward, rows, closing, totalDebit,totalCredit, buildRows, isBW = false, school }) {
  /* Same Colorful/Colorless convention as buildTxnReportHTML above:
     Colorless = paper-white, dark text, thin gray borders, no fills. */
  const thBg    = isBW ? '#FFFFFF' : '#1E3A8A';
  const thFg    = isBW ? '#0F172A' : '#FFFFFF';
  const thBdr   = isBW ? 'border-bottom:1.5px solid #0F172A;' : '';
  const openBg  = isBW ? '#FFFFFF' : '#F1F5F9';
  const tfBdr   = isBW ? '#0F172A' : '#111';
  const brand   = isBW ? '#0F172A' : '#1E3A8A';
  const logoHtml = school?.logo
    ? `<img src="${escHtmlAcc(school.logo)}" alt="logo" onerror="this.style.display='none'" />`
    : escHtmlAcc(school?.monogram || 'SM');  return `<!DOCTYPE html><html><head><meta charset="utf-8"><title>${escHtmlAcc(account.name)} Statement</title>
  <style>
    *{box-sizing:border-box;margin:0;padding:0} body{font-family:'Plus Jakarta Sans',Arial,sans-serif;color:#111;padding:24px}
    h1{font-size:16px;margin-bottom:2px} .sub{font-size:12px;color:#555;margin-bottom:16px}
    .head{display:flex;align-items:center;gap:12px;border-bottom:2px solid ${brand};padding-bottom:10px;margin-bottom:14px}
    .logo{width:46px;height:46px;border-radius:12px;background:${isBW ? '#fff' : 'linear-gradient(135deg,#1E3A8A,#1E40AF)'};color:${isBW ? '#111' : '#fff'};font-size:18px;font-weight:800;display:flex;align-items:center;justify-content:center;overflow:hidden;border:1px solid #E5E7EB;flex-shrink:0}
    .logo img{width:100%;height:100%;object-fit:contain;background:#fff}
    .school{font-size:17px;font-weight:800;color:${brand}}
    .addr,.session{font-size:10px;color:#64748B;margin-top:2px;font-weight:600}
    .meta{margin-left:auto;font-size:10px;color:#64748B;text-align:right;line-height:1.55}    table{width:100%;border-collapse:collapse;font-size:12px} th,td{padding:7px 8px;border-bottom:1px solid #e2e8f0;text-align:left}
    th{background:${thBg};color:${thFg};font-size:10.5px;text-transform:uppercase;${thBdr}} td.r,th.r{text-align:right}
    .open td{background:${openBg};font-weight:700} tfoot td{font-weight:800;border-top:2px solid ${tfBdr}}
  </style></head><body>
  <div class="head">
    <div class="logo">${logoHtml}</div>
    <div>
      <div class="school">${escHtmlAcc(school?.name || 'School')}</div>
      ${school?.address ? `<div class="addr">${escHtmlAcc(school.address)}</div>` : ''}
      ${school?.session ? `<div class="session">Academic Session: ${escHtmlAcc(school.session)}</div>` : ''}
    </div>
    <div class="meta">Generated: ${new Date().toLocaleDateString('en-GB')}<br/>By: ${escHtmlAcc(school?.generatedBy || 'Accounts')}</div>
  </div>
  <h1>${escHtmlAcc(account.name)} — Account Statement</h1>  <div class="sub">${from ? accFmtDate(from) : 'All time'} to ${to ? accFmtDate(to) : 'today'}</div>
  <table><thead><tr><th>Date</th><th>Description</th><th>Type</th><th class="r">Debit</th><th class="r">Credit</th><th class="r">Balance</th></tr></thead>
  <tbody>
    <tr class="open"><td>${openDate ? accFmtDate(openDate) : '—'}</td><td>${escHtmlAcc(openLabel)}</td><td>Opening</td><td class="r">—</td><td class="r">—</td><td class="r">${broughtForward.toLocaleString('en-PK')}</td></tr>
    ${buildRows()}
  </tbody>
  <tfoot><tr><td colspan="3">Period Totals</td><td class="r">${totalDebit.toLocaleString('en-PK')}</td><td class="r">${totalCredit.toLocaleString('en-PK')}</td><td class="r">${closing.toLocaleString('en-PK')}</td></tr></tfoot>
  </table>
  </body></html>`;
}

function buildFinStatementCSV({ account, from, to, openLabel, openDate, broughtForward, rows, closing }) {
  const esc = (s) => `"${String(s ?? '').replace(/"/g, '""')}"`;
  const lines = [
    `${account.name} Statement`,
    `${from || 'All time'} to ${to || 'today'}`,
    '',
    ['Date', 'Description', 'Type', 'Debit', 'Credit', 'Balance'].join(','),
    [accFmtDate(openDate), esc(openLabel), 'Opening', '', '', broughtForward].join(','),    ...rows.map(r => [accFmtDate(r.date), esc(r.desc), r.cat === 'transfer' ? 'Transfer' : (r.kind === 'credit' ? 'Credit' : 'Debit'), r.kind === 'debit' ? r.amount : '', r.kind === 'credit' ? r.amount : '', r.balance].join(',')),
    ['', 'Closing Balance', '', '', '', closing].join(','),
  ];
  return lines.join('\n');
}


function AccountBooks({ toast, isOtherSession }) {
  const { can } = usePermissions();
  const canBkCreate   = can('Accounts', 'Account Books', 'Create');
  const canBkEdit     = can('Accounts', 'Account Books', 'Edit');
  const canBkDelete   = can('Accounts', 'Account Books', 'Delete');
  const canBkDownload = can('Accounts', 'Account Books', 'Download');
  const { data: serverBooks = [], refetch: refetchBooks } = useAsync(accountsService.getAccBooks, []);
  const { data: users = [] }       = useAsync(accountsService.getAccUsers, []);
  const { data: currentUser = '' } = useAsync(accountsService.getAccCurrentUser, '');
  const school = useBranchSchool();

  const list = serverBooks || [];

  const [currentBookId, setCurrentBookId] = useState(null); // numeric book ID
  const [currentBook, setCurrentBook]     = useState(null); // fetched detail (book + txns)
  const [search, setSearch]               = useState('');
  const [status, setStatus]               = useState('all');
  const [editBook, setEditBook]           = useState(null); // { mode:'add'|'edit', book? }
  const [editTxn, setEditTxn]             = useState(null); // { mode:'add'|'edit', txn? }
  const [confirm, setConfirm]             = useState(null);
  const [helpOpen, setHelpOpen]           = useState(false);
  const [ledgerSearch, setLedgerSearch]   = useState('');
  const [ledgerFilter, setLedgerFilter]   = useState('all');
  const [ledgerSort, setLedgerSort]       = useState('desc');
  /* Book pending report generation — opens the shared style/format picker. */
  const [bookReportFor, setBookReportFor] = useState(null);

  /* Aggregate stats for the books-list explainer banner */
  let totBooks = list.length, totPayable = 0, totReceivable = 0, totCash = 0;
  list.forEach(b => {
    const c = bookCalc(b);
    totPayable += c.returnedAll;
    if (b.type === 'receivable') totReceivable += c.balance;
    if (b.includeInCash) totCash += c.balance;
  });

  const filteredBooks = useMemo(() => {
    const q = search.trim().toLowerCase();
    return list.filter(b => {
      if (status !== 'all' && b.status !== status) return false;
      if (q && !`${b.name} ${b.party || ''} ${b.desc || ''}`.toLowerCase().includes(q)) return false;
      return true;
    });
  }, [list, search, status]);

  /* Open a book → fetch its full ledger from the backend. */
  const loadDetail = useCallback(async (bookId) => {
    try {
      const detail = await accountsService.getAccBookDetail(bookId);
      setCurrentBook(detail);
    } catch (err) {
      toast(err?.message || 'Could not load account book', 'error');
      setCurrentBook(null);
      setCurrentBookId(null);
    }
  }, [toast]);

  const openBook = (b) => { setCurrentBookId(b.bookID); setCurrentBook(null); loadDetail(b.bookID); };

  /* Save / delete handlers — every action re-fetches so the list (and the
     open book's ledger) reflect the server's recalculated balances. */
  const handleSaveBook = async (form) => {
    const wasEdit = editBook.mode === 'edit';
    try {
      await accountsService.saveAccBook(form);
    } catch (err) {
      toast(err?.message || 'Could not save account book', 'error');
      return;
    }
    toast(wasEdit ? 'Book updated' : 'Account book created', 'success');
    setEditBook(null);
    refetchBooks();
    if (wasEdit && currentBookId) loadDetail(currentBookId);
  };

  const handleSaveBookTxn = async (form) => {
    if (!currentBookId) return;
    try {
      await accountsService.saveAccBookTxn({ bookId: currentBookId, ...form });
    } catch (err) {
      toast(err?.message || 'Could not save transaction', 'error');
      return;
    }
    toast(editTxn.mode === 'edit' ? 'Transaction updated' : 'Transaction added', 'success');
    setEditTxn(null);
    loadDetail(currentBookId);
    refetchBooks();
  };

  const requestDeleteBook = (b) => {
    setConfirm({
      title:   'Delete this account book?',
      message: <span><strong>{b.name}</strong> and all <strong>{b.txns?.length || 0}</strong> ledger entries will be permanently removed.</span>,
      hint:    'This action cannot be undone.',
      onConfirm: async () => {
        try {
          await accountsService.deleteAccBook(b.bookID);
        } catch (err) {
          toast(err?.message || 'Could not delete account book', 'error');
          return;
        }
        setCurrentBookId(null);
        setCurrentBook(null);
        toast('Account book deleted', 'success');
        refetchBooks();
      },
    });
  };

  const requestDeleteTxn = (t) => {
    setConfirm({
      title:   'Delete this ledger entry?',
      message: <span>The <strong>{t.type}</strong> entry of <strong>{fmtMoney(Math.abs(t.amount))}</strong> on {accFmtDate(t.date)} will be permanently removed.</span>,
      hint:    'The running balance will be re-calculated automatically.',
      onConfirm: async () => {
        try {
          await accountsService.deleteAccBookTxn(t.id);
        } catch (err) {
          toast(err?.message || 'Could not delete transaction', 'error');
          return;
        }
        toast('Ledger entry deleted', 'success');
        loadDetail(currentBookId);
        refetchBooks();
      },
    });
  };

  /* Generate the per-book A4 ledger report — opens a print window with
     embedded attachment images so receipts print alongside each entry.
     openBookReport just opens the shared style/format picker;
     generateBookReport does the actual build + dispatch once the user
     picks Colorful/Colorless and PDF/Word/Excel. */
  const openBookReport = (b) => setBookReportFor(b);
  const generateBookReport = async (style, format) => {
    const b = bookReportFor;
    if (!b) return;
    const isBW = style === 'bw';
    setBookReportFor(null);
    /* PDF: open the window inside the click gesture so it isn't pop-up blocked,
       then load the full ledger (list cards carry only aggregate totals). */
    const w = format === 'pdf' ? window.open('', '_blank') : null;
    if (format === 'pdf' && !w) { toast('Please allow pop-ups to download the report', 'error'); return; }
    let full = b;
    if (!b.txns || b.txns.length === 0) {
      try { full = await accountsService.getAccBookDetail(b.bookID); }
      catch (err) { toast(err?.message || 'Could not load book for report', 'error'); if (w) w.close(); return; }
    }
    const html = buildBookReportHTML({ book: full, school, isBW });
    const filename = `${String(full.name || 'Account-Book').replace(/[^A-Za-z0-9]+/g, '-')}-ledger`;
    if (format === 'word') {
      downloadReportAsWord(html, `${filename}.doc`);
    } else if (format === 'excel') {
      downloadReportHtmlAsExcel(html, `${filename}.xls`);
    } else {
      w.document.write(html);
      w.document.close();
      w.onload = () => { try { w.focus(); w.print(); } catch (e) { /* ignore */ } };
    }
    toast(`${full.name} ledger report ready (${isBW ? 'Colorless' : 'Colorful'}) — ${format.toUpperCase()}.`, 'success');
  };

  return (
    <>
      {!currentBookId ? (
        /* ── LIST VIEW ── */
        <>
          <div className="acc-overview acc-books-explainer">
            <div className="acc-overview-main">
              <div className="acc-overview-icon" style={{ background: 'linear-gradient(135deg,#7C3AED,#6D28D9)' }}>
                <i className="fa-solid fa-book-open"></i>
              </div>
              <div className="acc-overview-text">
                <div className="acc-overview-title">
                  Account Books <span className="acc-books-tagchip">Supplier, Vendor &amp; Party Ledgers</span>
                </div>
                <div className="acc-overview-sub">
                  A running account with any party the school owes or is owed — <strong>suppliers, vendors, contractors, service providers, owners or investors</strong>. Track uniforms, books or stationery bought on credit, loans, advances and contributions. Each book keeps a running balance with full history.{' '}
                  <button className="acc-link-btn" onClick={() => setHelpOpen(true)}>
                    <i className="fa-solid fa-circle-question"></i> How does this work?
                  </button>
                </div>
              </div>
            </div>
            <div className="acc-overview-stats">
              <div className="acc-ov-stat">
                <div className="acc-ov-stat-ic" style={{ background: 'linear-gradient(135deg,#7C3AED,#6D28D9)' }}><i className="fa-solid fa-book"></i></div>
                <div>
                  <div className="acc-ov-stat-val">{totBooks}</div>
                  <div className="acc-ov-stat-lbl">Total Books</div>
                </div>
              </div>
              <div className="acc-ov-stat">
                <div className="acc-ov-stat-ic" style={{ background: 'linear-gradient(135deg,#DC2626,#B91C1C)' }}><i className="fa-solid fa-arrow-up"></i></div>
                <div>
                  <div className="acc-ov-stat-val">{fmtMoney(totPayable)}</div>
                  <div className="acc-ov-stat-lbl">Net Payable</div>
                </div>
              </div>
              <div className="acc-ov-stat">
                <div className="acc-ov-stat-ic" style={{ background: 'linear-gradient(135deg,#0891B2,#0E7490)' }}><i className="fa-solid fa-wallet"></i></div>
                <div>
                  <div className="acc-ov-stat-val">{fmtMoney(totCash)}</div>
                  <div className="acc-ov-stat-lbl">In Cash Hand</div>
                </div>
              </div>
              <div className="acc-ov-stat">
                <div className="acc-ov-stat-ic" style={{ background: 'linear-gradient(135deg,#16A34A,#15803D)' }}><i className="fa-solid fa-arrow-down"></i></div>
                <div>
                  <div className="acc-ov-stat-val">{fmtMoney(totReceivable)}</div>
                  <div className="acc-ov-stat-lbl">Net Receivable</div>
                </div>
              </div>
            </div>
          </div>

          <div className="fee-section">
            <div className="fee-section-body">
              <div className="fee-filters">
                <div className="fee-field" style={{ flex: 1, minWidth: 240 }}>
                  <span className="fee-label">Search Books</span>
                  <div className="fee-search-box">
                    <i className="fa-solid fa-magnifying-glass"></i>
                    <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search by book name, party or description" />
                    {search && (
                      <Tooltip text="Clear search">
                        <button className="fee-search-clear" onClick={() => setSearch('')} aria-label="Clear search">
                          <i className="fa-solid fa-xmark"></i>
                        </button>
                      </Tooltip>
                    )}
                  </div>
                </div>
                <div className="fee-field">
                  <span className="fee-label">Status</span>
                  <div className="fee-select-wrap">
                    <select className="fee-select" value={status} onChange={e => setStatus(e.target.value)}>
                      <option value="all">All Books</option>
                      <option value="active">Active</option>
                      <option value="settled">Settled</option>
                      <option value="closed">Closed</option>
                    </select>
                    <i className="fa-solid fa-chevron-down"></i>
                  </div>
                </div>
                <Tooltip text={!canBkCreate ? 'You do not have permission to add account books' : 'Open a new running account with a party'}>
                  <button
                    className="fee-btn fee-btn-primary"
                    onClick={() => { if (isOtherSession) { toast('Method not allowed', 'error'); return; } setEditBook({ mode: 'add' }); }}
                    disabled={isOtherSession || !canBkCreate}
                    title={!canBkCreate ? 'You do not have permission to add account books' : isOtherSession ? 'Editing is only allowed for the current session' : undefined}
                    style={(isOtherSession || !canBkCreate) ? { opacity: .45, cursor: 'not-allowed' } : undefined}
                  >
                    <i className="fa-solid fa-plus"></i> Add New Account Book
                  </button>
                </Tooltip>
              </div>
            </div>
          </div>

          {filteredBooks.length === 0 ? (
            <div className="acc-ledger-empty">
              <i className="fa-solid fa-book-open"></i>
              No account books found.<br/>
              Use <strong>Add New Account Book</strong> to create one.
            </div>
          ) : (
            <div className="acc-books-grid">
              {filteredBooks.map(b => {
                const c = bookCalc(b);
                return (
                  <button type="button" key={b.id} className="acc-book-card" onClick={() => openBook(b)}>
                    <div className="acc-book-card-top">
                      <div className="acc-book-card-ic"><i className="fa-solid fa-book-bookmark"></i></div>
                      <div className="acc-book-card-tt">
                        <div className="acc-book-card-name">{b.name}</div>
                        <div className="acc-book-card-party">
                          <i className="fa-solid fa-user"></i> {b.party || '—'} · {b.type === 'payable' ? 'Payable' : 'Receivable'}
                        </div>
                      </div>
                      <span className={`acc-book-status ${b.status}`}>{b.status}</span>
                    </div>
                    <div className="acc-book-card-body">
                      <div className="acc-book-bal-row">
                        <div>
                          <div className="acc-book-bal-lbl">{b.type === 'payable' ? 'Remaining Payable' : 'Remaining Receivable'}</div>
                          {/* Minus balance = party ko jitna dena tha us se zyada ja chuka
                              hai — laal rang me taake ek nazar me pata chale. */}
                          <div className="acc-book-bal-val" style={c.balance < 0 ? { color: '#DC2626' } : undefined}>{fmtMoney(c.balance)}</div>
                        </div>
                      </div>
                      <div className="acc-book-card-mini">
                        <div className="acc-book-mini">
                          <div className="acc-book-mini-l">Total In</div>
                          <div className="acc-book-mini-v in">{fmtMoney(c.totalIn)}</div>
                        </div>
                        <div className="acc-book-mini">
                          <div className="acc-book-mini-l">Returned</div>
                          <div className="acc-book-mini-v out">{fmtMoney(c.returnedAll)}</div>
                        </div>
                      </div>
                    </div>
                    <div className="acc-book-card-foot">
                      <span className="acc-book-card-meta"><i className="fa-regular fa-clock"></i> {accFmtDate(c.lastDate)}</span>
                      <div className="acc-book-card-foot-r">
                        {b.includeInCash
                          ? <span className="acc-book-cashtag"><i className="fa-solid fa-wallet"></i> In Cash</span>
                          : <span className="acc-book-card-meta">{b.txns.length} txns</span>}
                        {canBkDownload && (
                        <Tooltip text={`Download ${b.name} A4 ledger report`}>
                          <span
                            role="button"
                            tabIndex={0}
                            className="acc-book-card-dl"
                            onClick={e => { e.stopPropagation(); openBookReport(b); }}
                            onKeyDown={e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); e.stopPropagation(); openBookReport(b); } }}
                          >
                            <i className="fa-solid fa-file-arrow-down"></i>
                          </span>
                        </Tooltip>
                        )}
                      </div>
                    </div>
                  </button>
                );
              })}
            </div>
          )}
        </>
      ) : !currentBook ? (
        /* ── DETAIL LOADING ── */
        <div className="acc-ledger-empty">
          <i className="fa-solid fa-spinner fa-spin"></i>
          Loading account book…
        </div>
      ) : (
        /* ── DETAIL VIEW ── */
        <BookDetail
          book={currentBook}
          users={users}
          ledgerSearch={ledgerSearch} setLedgerSearch={setLedgerSearch}
          ledgerFilter={ledgerFilter} setLedgerFilter={setLedgerFilter}
          ledgerSort={ledgerSort}     setLedgerSort={setLedgerSort}
          onBack={() => { setCurrentBookId(null); setCurrentBook(null); }}
          onEditBook={() => setEditBook({ mode: 'edit', book: currentBook })}
          onDeleteBook={() => requestDeleteBook(currentBook)}
          onDownloadReport={() => openBookReport(currentBook)}
          onAddTxn={() => setEditTxn({ mode: 'add' })}
          onEditTxn={(t) => setEditTxn({ mode: 'edit', txn: t })}
          onDeleteTxn={requestDeleteTxn}
          canBkCreate={canBkCreate} canBkEdit={canBkEdit} canBkDelete={canBkDelete} canBkDownload={canBkDownload}
          toast={toast}
          isOtherSession={isOtherSession}
        />
      )}

      <BookEditModal cfg={editBook} users={users} currentUser={currentUser} onClose={() => setEditBook(null)} onSave={handleSaveBook} toast={toast} />
      <BookTxnModal  cfg={editTxn}  users={users} currentUser={currentUser} book={currentBook} onClose={() => setEditTxn(null)} onSave={handleSaveBookTxn} toast={toast} />
      <AccConfirmDialog cfg={confirm} onClose={() => setConfirm(null)} />
      <BooksHelpModal open={helpOpen} onClose={() => setHelpOpen(false)} />
      {bookReportFor && (
        <StandardReportPicker
          open
          title={`${bookReportFor.name} — Ledger Report`}
          subtitle="Choose style and format, then generate."
          formats={['pdf', 'word', 'excel']}
          onClose={() => setBookReportFor(null)}
          onGenerate={generateBookReport}
        />
      )}
    </>
  );
}

/* ─── Book detail view ─── */
function BookDetail({
  book, users, ledgerSearch, setLedgerSearch, ledgerFilter, setLedgerFilter,
  ledgerSort, setLedgerSort, onBack, onEditBook, onDeleteBook, onDownloadReport,
  onAddTxn, onEditTxn, onDeleteTxn, isOtherSession,
  canBkCreate = true, canBkEdit = true, canBkDelete = true, canBkDownload = true,
}) {
  const [openLedgerId, setOpenLedgerId] = useState(null);
  const c = bookCalc(book);
  const q = ledgerSearch.trim().toLowerCase();
  let rows = [...c.withBal];
  if (ledgerFilter !== 'all') rows = rows.filter(t => t.type === ledgerFilter);
  if (q) rows = rows.filter(t => `${t.notes || ''} ${t.enteredBy || ''} ${t.amount}`.toLowerCase().includes(q));
  rows.sort((a, b2) => ledgerSort === 'asc' ? (a.date < b2.date ? -1 : 1) : (a.date > b2.date ? -1 : 1));

  const TLABEL = { received: 'Received', returned: 'Returned', adjustment: 'Adjustment' };
  const SIGN   = { received: '+', returned: '−', adjustment: '' };

  return (
    <>
      <div className="acc-book-topbar">
        <Tooltip text="Back to all books">
          <button className="fee-btn fee-btn-ghost" onClick={onBack}>
            <i className="fa-solid fa-arrow-left"></i> All Books
          </button>
        </Tooltip>
        <div className="acc-book-topbar-title">{book.name}</div>
        <div className="acc-book-topbar-actions">
          <span className={`acc-book-status ${book.status}`}>{book.status}</span>
          {canBkDownload && (
          <Tooltip text="Download a detailed A4 PDF ledger report (includes attachment images)">
            <button className="fee-btn fee-btn-primary acc-btn-download" onClick={onDownloadReport}>
              <i className="fa-solid fa-file-arrow-down"></i> Ledger Report
            </button>
          </Tooltip>
          )}
          {canBkEdit && (
          <Tooltip text="Edit book details">
            <button
              className="fee-btn fee-btn-ghost"
              onClick={onEditBook}
              disabled={isOtherSession}
              title={isOtherSession ? 'Editing is only allowed for the current session' : undefined}
              style={isOtherSession ? { opacity: .45, cursor: 'not-allowed' } : undefined}
            >
              <i className="fa-solid fa-pen"></i> Edit Book
            </button>
          </Tooltip>
          )}
          {canBkDelete && (
          <Tooltip text="Delete this book and all ledger entries">
            <button
              className="fee-btn fee-btn-ghost acc-btn-danger"
              onClick={onDeleteBook}
              disabled={isOtherSession}
              title={isOtherSession ? 'Editing is only allowed for the current session' : undefined}
              style={isOtherSession ? { opacity: .45, cursor: 'not-allowed' } : undefined}
            >
              <i className="fa-solid fa-trash-can"></i> Delete Book
            </button>
          </Tooltip>
          )}
        </div>
      </div>

      <div className="acc-book-summary">
        <div className="acc-bsum b-opening">
          <div className="acc-bsum-top"><span className="acc-bsum-lbl">Opening Amount</span><span className="acc-bsum-ic"><i className="fa-solid fa-flag"></i></span></div>
          <div className="acc-bsum-val">{fmtMoney(book.opening)}</div>
          <div className="acc-bsum-meta">{accFmtDate(book.openDate)}</div>
        </div>
        <div className="acc-bsum b-balance">
          <div className="acc-bsum-top"><span className="acc-bsum-lbl">Current Balance</span><span className="acc-bsum-ic"><i className="fa-solid fa-scale-balanced"></i></span></div>
          <div className="acc-bsum-val" style={c.balance < 0 ? { color: '#DC2626' } : undefined}>{fmtMoney(c.balance)}</div>
          <div className="acc-bsum-meta">{book.type === 'payable' ? 'payable to party' : 'receivable'}</div>
        </div>
        <div className="acc-bsum b-in">
          <div className="acc-bsum-top"><span className="acc-bsum-lbl">Total Received</span><span className="acc-bsum-ic"><i className="fa-solid fa-arrow-down"></i></span></div>
          <div className="acc-bsum-val">{fmtMoney(c.totalIn)}</div>
          <div className="acc-bsum-meta">amount received</div>
        </div>
        <div className="acc-bsum b-out">
          <div className="acc-bsum-top"><span className="acc-bsum-lbl">Total Returned</span><span className="acc-bsum-ic"><i className="fa-solid fa-arrow-up"></i></span></div>
          <div className="acc-bsum-val">{fmtMoney(c.returnedAll)}</div>
          <div className="acc-bsum-meta">paid back</div>
        </div>
        <div className="acc-bsum b-cash">
          <div className="acc-bsum-top"><span className="acc-bsum-lbl">Cash In Hand</span><span className="acc-bsum-ic"><i className="fa-solid fa-wallet"></i></span></div>
          <div className="acc-bsum-val sm">{book.includeInCash ? 'Included' : 'Excluded'}</div>
          <div className="acc-bsum-meta">{book.includeInCash ? 'affects cash only' : 'not in cash calc'}</div>
        </div>
        <div className="acc-bsum b-date">
          <div className="acc-bsum-top"><span className="acc-bsum-lbl">Last Transaction</span><span className="acc-bsum-ic"><i className="fa-regular fa-clock"></i></span></div>
          <div className="acc-bsum-val sm">{accFmtDate(c.lastDate)}</div>
          <div className="acc-bsum-meta">{book.txns.length} entries</div>
        </div>
      </div>

      <div className={`acc-cash-strip ${book.includeInCash ? 'on' : 'off'}`}>
        <div className="acc-cash-strip-ic"><i className="fa-solid fa-wallet"></i></div>
        <div className="acc-cash-strip-txt">
          <div className="acc-cash-strip-t">{book.includeInCash ? 'Included in Cash In Hand' : 'Not included in Cash In Hand'}</div>
          <div className="acc-cash-strip-d">
            {book.includeInCash
              ? 'This book\'s balance is added to Cash In Hand only — it does not affect Profit & Loss.'
              : 'Enable this in the book settings if the school physically holds this cash.'}
          </div>
        </div>
        <Tooltip text="Edit the book to toggle">
          <button
            className="fee-btn fee-btn-ghost"
            onClick={onEditBook}
            disabled={isOtherSession}
            title={isOtherSession ? 'Editing is only allowed for the current session' : undefined}
            style={isOtherSession ? { opacity: .45, cursor: 'not-allowed' } : undefined}
          >
            <i className="fa-solid fa-pen"></i> Edit Book
          </button>
        </Tooltip>
      </div>

      <div className="acc-ledger-toolbar">
        <div className="acc-ledger-toolbar-l">
          <div className="fee-search-box" style={{ maxWidth: 280 }}>
            <i className="fa-solid fa-magnifying-glass"></i>
            <input value={ledgerSearch} onChange={e => setLedgerSearch(e.target.value)} placeholder="Search transactions" />
          </div>
          <div className="fee-select-wrap">
            <select className="fee-select" value={ledgerFilter} onChange={e => setLedgerFilter(e.target.value)} style={{ minWidth: 148 }}>
              <option value="all">All Types</option>
              <option value="received">Received</option>
              <option value="returned">Returned</option>
              <option value="adjustment">Adjustment</option>
            </select>
            <i className="fa-solid fa-chevron-down"></i>
          </div>
          <div className="fee-select-wrap">
            <select className="fee-select" value={ledgerSort} onChange={e => setLedgerSort(e.target.value)} style={{ minWidth: 140 }}>
              <option value="desc">Newest First</option>
              <option value="asc">Oldest First</option>
            </select>
            <i className="fa-solid fa-chevron-down"></i>
          </div>
        </div>
        {canBkCreate && (
        <Tooltip text="Record a new ledger entry">
          <button
            className="fee-btn fee-btn-primary"
            onClick={onAddTxn}
            disabled={isOtherSession}
            title={isOtherSession ? 'Editing is only allowed for the current session' : undefined}
            style={isOtherSession ? { opacity: .45, cursor: 'not-allowed' } : undefined}
          >
            <i className="fa-solid fa-plus"></i> Add Transaction
          </button>
        </Tooltip>
        )}
      </div>

      <div className="fee-section">
        <div className="fee-section-header">
          <div className="fee-section-title">
            <div className="fee-section-icon"><i className="fa-solid fa-timeline"></i></div>
            <div>
              <div className="fee-section-name">Transaction Ledger</div>
              <div className="fee-section-sub">{book.txns.length} transactions · current balance {fmtMoney(c.balance)}</div>
            </div>
          </div>
          <span className="fee-chip fee-chip-active"><i className="fa-solid fa-list"></i> {rows.length}</span>
        </div>
        <div className="acc-ledger">
          {rows.length === 0 ? (
            <div className="acc-ledger-empty">
              <i className="fa-solid fa-inbox"></i>
              No transactions yet.<br/>
              Use <strong>Add Transaction</strong> to record a movement.
            </div>
          ) : rows.map(t => {
            const isOpen = openLedgerId === t.id;
            const toggle = () => setOpenLedgerId(isOpen ? null : t.id);
            const atStamp = accFmtStamp(t.at || `${t.date}T00:00:00`);
            return (
              <div key={t.id} className="acc-ledger-item">
                <div className={`acc-ledger-dot ${t.type}`}>
                  <i className={`fa-solid ${t.type === 'received' ? 'fa-arrow-down' : t.type === 'returned' ? 'fa-arrow-up' : 'fa-sliders'}`}></i>
                </div>
                <div className={`acc-ledger-card${isOpen ? ' open' : ''}`}>
                  <div className="acc-ledger-main" onClick={toggle}>
                    <span className={`acc-ledger-typetag ${t.type}`}>{TLABEL[t.type]}</span>
                    <div className="acc-ledger-info">
                      <div className="acc-ledger-notes">{t.notes || '—'}</div>
                      <div className="acc-ledger-sub">
                        <span><i className="fa-regular fa-calendar"></i> {accFmtDate(t.date)}</span>
                        <span><i className="fa-solid fa-user-pen"></i> {t.enteredBy || '—'}</span>
                        {t.attachments && t.attachments.length > 0 && (
                          <span><i className="fa-solid fa-paperclip"></i> {t.attachments.length} file{t.attachments.length > 1 ? 's' : ''}</span>
                        )}
                      </div>
                    </div>
                    <div className="acc-ledger-amt">
                      <div className={`acc-ledger-amt-v ${t.type}`}>
                        {SIGN[t.type]}{fmtMoney(Math.abs(t.amount))}
                      </div>
                      <div className="acc-ledger-amt-bal">Bal: {fmtMoney(t.runningBalance)}</div>
                    </div>
                    <Tooltip text={isOpen ? 'Hide details' : 'Show details'}>
                      <button
                        type="button"
                        className="acc-ledger-chev"
                        onClick={e => { e.stopPropagation(); toggle(); }}
                      >
                        <i className="fa-solid fa-chevron-down"></i>
                      </button>
                    </Tooltip>
                  </div>
                  <div className="acc-ledger-expand">
                    <div className="acc-ledger-expand-in">
                      <div className="acc-ledger-kv">
                        <span className="k">Type</span>          <span className="v">{TLABEL[t.type]}</span>
                        <span className="k">Amount</span>        <span className="v">{fmtMoney(t.amount)}</span>
                        <span className="k">Date &amp; Time</span><span className="v">{atStamp}</span>
                        <span className="k">Entered By</span>    <span className="v">{t.enteredBy || '—'}</span>
                        <span className="k">Balance After</span> <span className="v">{fmtMoney(t.runningBalance)}</span>
                        <span className="k">Notes</span>         <span className="v">{t.notes || '—'}</span>
                      </div>

                      {t.attachments && t.attachments.length > 0 ? (
                        <>
                          <div className="acc-ledger-attachhead">
                            <i className="fa-solid fa-paperclip"></i> Attachments
                          </div>
                          <div className="acc-attach-previews">
                            {t.attachments.map((a, i) => {
                              const src = a.url || a.data;
                              return (
                                <div key={i} className="acc-attach-preview">
                                  <div className="acc-attach-preview-head">
                                    <div className={`acc-attach-thumb-ic ${a.kind || 'img'}`}>
                                      <i className={`fa-solid ${a.kind === 'pdf' ? 'fa-file-pdf' : 'fa-image'}`}></i>
                                    </div>
                                    <div>
                                      <div className="acc-attach-thumb-nm">{a.name}</div>
                                      <div className="acc-attach-thumb-sz">{a.size || (a.kind === 'pdf' ? 'PDF document' : 'Image attachment')}</div>
                                    </div>
                                    <Tooltip text="Open attachment in new tab">
                                      <a
                                        className="acc-attach-open"
                                        href={src}
                                        target="_blank"
                                        rel="noopener noreferrer"
                                        aria-label={`Open ${a.name}`}
                                      >
                                        <i className="fa-solid fa-up-right-from-square"></i>
                                      </a>
                                    </Tooltip>
                                  </div>
                                  {a.kind === 'pdf' ? (
                                    <iframe className="acc-attach-preview-pdf" src={src} title={a.name} />
                                  ) : (
                                    <img className="acc-attach-preview-img" src={src} alt={a.name} />
                                  )}
                                </div>
                              );
                            })}
                          </div>
                        </>
                      ) : (
                        <div className="acc-ledger-attachhead">
                          <i className="fa-solid fa-paperclip"></i> No attachments
                        </div>
                      )}

                      <div className="acc-ledger-actions-row">
                        {canBkEdit && (
                        <Tooltip text="Edit this ledger entry">
                          <button
                            className="fee-btn fee-btn-ghost"
                            onClick={() => onEditTxn(t)}
                            disabled={isOtherSession}
                            title={isOtherSession ? 'Editing is only allowed for the current session' : undefined}
                            style={isOtherSession ? { opacity: .45, cursor: 'not-allowed' } : undefined}
                          >
                            <i className="fa-solid fa-pen"></i> Edit
                          </button>
                        </Tooltip>
                        )}
                        {canBkDelete && (
                        <Tooltip text="Delete this ledger entry">
                          <button
                            className="fee-btn fee-btn-ghost acc-ledger-del"
                            onClick={() => onDeleteTxn(t)}
                            disabled={isOtherSession}
                            title={isOtherSession ? 'Editing is only allowed for the current session' : undefined}
                            style={isOtherSession ? { opacity: .45, cursor: 'not-allowed' } : undefined}
                          >
                            <i className="fa-solid fa-trash-can"></i> Delete
                          </button>
                        </Tooltip>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </>
  );
}

/* ═══════════════════════════════════════════════════════════════════
   A4 PDF builder for one Account Book — emits a print-window HTML
   document with:
   • School-branded header + book identity card
   • 6-card summary strip (opening, balance, in/out, status, cash flag)
   • Description block
   • Full transaction ledger with running balance
   • Embedded attachment images (data-URL <img>) per entry
   • PDF attachments shown as labeled placeholder cards
   ═══════════════════════════════════════════════════════════════════ */
function buildBookReportHTML({ book, school, isBW = false }) {
  const escH = (s) => String(s ?? '').replace(/[&<>"']/g, m => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[m]));
  const c = bookCalc(book);
  const sorted = [...c.withBal].sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
  const today = school?.generatedDate ? accFmtStamp(school.generatedDate) : new Date().toLocaleDateString('en-GB');
  /* Real branch logo from /report-header; monogram only if logo missing. */
  const logoHtml = school?.logo
    ? `<img src="${escH(school.logo)}" alt="${escH(school?.name || 'Branch')} logo" onerror="this.style.display='none'" />`
    : escH(school?.monogram || 'SM');
  const TLABEL = { received: 'Received', returned: 'Returned', adjustment: 'Adjustment' };
  const SIGN   = { received: '+', returned: '−', adjustment: '' };
  const COLORS = {
    received:   { fg: '#16A34A', bg: 'rgba(22,163,74,.10)',  bd: 'rgba(22,163,74,.28)' },
    returned:   { fg: '#DC2626', bg: 'rgba(220,38,38,.08)',  bd: 'rgba(220,38,38,.22)' },
    adjustment: { fg: '#2563EB', bg: 'rgba(37,99,235,.10)',  bd: 'rgba(37,99,235,.25)' },
  };

  /* One ledger entry block (with embedded attachments). Each entry is
     a self-contained card with header / detail / attachment grid. */
  const entryBlock = (t, i) => {
    const col = COLORS[t.type] || COLORS.received;
    const atts = Array.isArray(t.attachments) ? t.attachments : [];
    const images = atts.filter(a => a.kind === 'img' && a.data);
    const pdfs   = atts.filter(a => a.kind === 'pdf');
    const stamp  = t.at
      ? `${t.date} · ${new Date(t.at).toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', hour12: true })}`
      : t.date;
    return `
    <div class="entry">
      <div class="entry-head">
        <div class="entry-no">${i + 1}</div>
        <div class="entry-head-main">
          <span class="entry-tag" style="background:${col.bg};color:${col.fg};border-color:${col.bd}">${TLABEL[t.type] || t.type}</span>
          <div class="entry-notes">${escH(t.notes) || '—'}</div>
        </div>
        <div class="entry-amt-block">
          <div class="entry-amt" style="color:${col.fg}">${SIGN[t.type]}Rs. ${(Math.abs(t.amount)).toLocaleString('en-PK')}</div>
          <div class="entry-bal">Running Bal Rs. ${(t.runningBalance).toLocaleString('en-PK')}</div>
        </div>
      </div>
      <div class="entry-meta">
        <span><b>Date &amp; Time:</b> ${escH(stamp)}</span>
        <span><b>Entered By:</b> ${escH(t.enteredBy || '—')}</span>
        ${atts.length ? `<span><b>Attachments:</b> ${atts.length} file${atts.length > 1 ? 's' : ''}</span>` : ''}
      </div>
      ${images.length > 0 ? `
        <div class="entry-attach-h"><i>📎</i> Attached Receipts &amp; Documents</div>
        <div class="entry-attach-grid">
          ${images.map(a => `
            <div class="attach-card">
              <div class="attach-card-imgwrap">
                <img src="${a.data}" alt="${escH(a.name)}" />
              </div>
              <div class="attach-card-foot">
                <div class="attach-card-nm">${escH(a.name)}</div>
                <div class="attach-card-sz">${escH(a.size)}</div>
              </div>
            </div>
          `).join('')}
        </div>` : ''}
      ${pdfs.length > 0 ? `
        ${images.length === 0 ? '<div class="entry-attach-h"><i>📎</i> Attached Documents</div>' : ''}
        <div class="entry-pdf-grid">
          ${pdfs.map(a => `
            <div class="pdf-card">
              <div class="pdf-card-ic">PDF</div>
              <div>
                <div class="pdf-card-nm">${escH(a.name)}</div>
                <div class="pdf-card-sz">${escH(a.size)} · attached PDF document</div>
              </div>
            </div>
          `).join('')}
        </div>` : ''}
    </div>`;
  };

  const STATUS_COLORS = {
    active:  { fg: '#15803D', bg: 'rgba(22,163,74,.12)',  bd: 'rgba(22,163,74,.25)' },
    settled: { fg: '#1E40AF', bg: 'rgba(30,58,138,.08)',  bd: 'rgba(30,58,138,.22)' },
    closed:  { fg: '#B91C1C', bg: 'rgba(220,38,38,.08)',  bd: 'rgba(220,38,38,.2)' },
  };
  const stat = STATUS_COLORS[book.status] || STATUS_COLORS.active;

  return `<!DOCTYPE html><html><head><meta charset="utf-8"><title>${escH(book.name)} — Ledger Report</title>
<style>
*{box-sizing:border-box;margin:0;padding:0}
html,body{font-family:'Plus Jakarta Sans','Segoe UI',Arial,sans-serif;color:#111;font-size:10.5px;line-height:1.5;}
body{background:#F1F3F8;padding:18px 0;}
.page{width:210mm;min-height:297mm;margin:0 auto;padding:14mm;background:#fff;box-shadow:0 10px 30px rgba(15,23,42,.12);box-sizing:border-box;}
.head{display:flex;align-items:center;gap:14px;border-bottom:2px solid #7C3AED;padding-bottom:10px;margin-bottom:14px;}
.logo{width:48px;height:48px;border-radius:14px;background:linear-gradient(135deg,#7C3AED,#6D28D9);color:#fff;font-size:20px;font-weight:800;display:flex;align-items:center;justify-content:center;flex-shrink:0;overflow:hidden;border:1px solid #E5E7EB;}
.logo img{width:100%;height:100%;object-fit:contain;background:#fff;display:block;}
.school{font-size:17px;font-weight:800;color:#1E3A8A;}
.title{font-size:12px;font-weight:700;color:#6D28D9;margin-top:3px;}
.addr{font-size:10px;color:#64748B;margin-top:2px;font-weight:600;}
.session{font-size:10px;color:#64748B;margin-top:1px;font-weight:600;}
.meta{margin-left:auto;font-size:9.5px;color:#64748B;text-align:right;line-height:1.55;}

.book-card{margin-bottom:12px;padding:14px 16px;border-radius:10px;border:1.5px solid #E5E7EB;background:linear-gradient(135deg,rgba(124,58,237,.04),transparent 60%);}
.book-card-head{display:flex;align-items:center;gap:12px;margin-bottom:8px;}
.book-card-ic{width:38px;height:38px;border-radius:11px;background:linear-gradient(135deg,#7C3AED,#6D28D9);color:#fff;display:flex;align-items:center;justify-content:center;font-size:16px;font-weight:800;flex-shrink:0;}
.book-card-name{font-size:16px;font-weight:800;color:#0F172A;letter-spacing:-.01em;}
.book-card-party{font-size:11.5px;color:#64748B;margin-top:2px;}
.status-pill{display:inline-block;padding:3px 12px;border-radius:999px;font-size:10px;font-weight:800;letter-spacing:.3px;text-transform:uppercase;border:1px solid;background:${stat.bg};color:${stat.fg};border-color:${stat.bd};margin-left:auto;}
.book-card-desc{font-size:11px;color:#475569;line-height:1.6;margin-top:6px;padding-top:8px;border-top:1px dashed #cbd5e1;}

.kpi-row{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:14px;}
.kpi{border:1px solid #E5E7EB;border-radius:8px;padding:8px 10px;background:#F8FAFF;position:relative;overflow:hidden;}
.kpi::before{content:'';position:absolute;left:0;top:0;bottom:0;width:3px;}
.kpi.opening::before{background:linear-gradient(180deg,#2563EB,#1E40AF);}
.kpi.balance::before{background:linear-gradient(180deg,#7C3AED,#6D28D9);}
.kpi.received::before{background:linear-gradient(180deg,#16A34A,#15803D);}
.kpi.returned::before{background:linear-gradient(180deg,#DC2626,#B91C1C);}
.kpi.cash::before{background:linear-gradient(180deg,#0891B2,#0E7490);}
.kpi.date::before{background:linear-gradient(180deg,#D97706,#B45309);}
.kpi .l{font-size:9px;font-weight:700;color:#64748B;text-transform:uppercase;letter-spacing:.3px;}
.kpi .v{font-size:14px;font-weight:800;color:#0F172A;margin-top:2px;font-variant-numeric:tabular-nums;}
.kpi .v.green{color:#15803D;} .kpi .v.red{color:#B91C1C;} .kpi .v.purple{color:#6D28D9;}
.kpi .m{font-size:9px;color:#64748B;margin-top:1px;}

.cash-info{padding:9px 12px;border-radius:8px;background:rgba(8,145,178,.06);border:1px solid rgba(8,145,178,.25);color:#0E7490;font-size:11px;margin-bottom:14px;font-weight:600;}
.cash-info b{color:#0E7490;}

.sec-band{background:linear-gradient(135deg,#7C3AED,#6D28D9);color:#fff;padding:8px 14px;border-radius:6px;font-weight:800;margin-bottom:10px;font-size:12px;display:flex;justify-content:space-between;align-items:center;}
.sec-band small{font-weight:700;opacity:.85;font-size:10px;}

.entry{border:1px solid #E5E7EB;border-radius:10px;padding:11px 14px;margin-bottom:10px;background:#fff;page-break-inside:avoid;}
.entry-head{display:flex;align-items:flex-start;gap:11px;}
.entry-no{width:24px;height:24px;border-radius:7px;background:linear-gradient(135deg,#1E3A8A,#1E40AF);color:#fff;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:11px;flex-shrink:0;}
.entry-head-main{flex:1;min-width:0;}
.entry-tag{display:inline-block;padding:2px 9px;border-radius:999px;font-size:9.5px;font-weight:800;letter-spacing:.3px;text-transform:uppercase;border:1px solid;}
.entry-notes{font-size:12px;font-weight:700;color:#0F172A;margin-top:5px;line-height:1.55;}
.entry-amt-block{text-align:right;flex-shrink:0;white-space:nowrap;}
.entry-amt{font-size:14px;font-weight:800;font-variant-numeric:tabular-nums;}
.entry-bal{font-size:10px;color:#64748B;margin-top:2px;}
.entry-meta{display:flex;flex-wrap:wrap;gap:4px 16px;font-size:10.5px;color:#475569;margin-top:8px;padding-top:7px;border-top:1px dashed #e2e8f0;}
.entry-meta b{color:#1E3A8A;font-weight:700;margin-right:3px;}

.entry-attach-h{margin-top:11px;font-size:10px;font-weight:800;letter-spacing:.4px;text-transform:uppercase;color:#6D28D9;display:flex;align-items:center;gap:6px;}
.entry-attach-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:9px;margin-top:7px;}
.attach-card{border:1px solid #E5E7EB;border-radius:8px;background:#fafafa;overflow:hidden;page-break-inside:avoid;}
.attach-card-imgwrap{width:100%;background:#f5f5f5;padding:6px;display:flex;align-items:center;justify-content:center;}
.attach-card-imgwrap img{max-width:100%;max-height:220px;height:auto;border-radius:4px;display:block;}
.attach-card-foot{padding:6px 9px;border-top:1px solid #eee;}
.attach-card-nm{font-size:10.5px;font-weight:700;color:#0F172A;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.attach-card-sz{font-size:9px;color:#64748B;margin-top:1px;}
.entry-pdf-grid{display:flex;flex-wrap:wrap;gap:8px;margin-top:7px;}
.pdf-card{display:flex;align-items:center;gap:9px;padding:8px 11px;border:1px dashed #B91C1C;border-radius:8px;background:rgba(220,38,38,.04);}
.pdf-card-ic{width:34px;height:34px;border-radius:7px;background:linear-gradient(135deg,#DC2626,#B91C1C);color:#fff;font-size:11px;font-weight:800;display:flex;align-items:center;justify-content:center;flex-shrink:0;}
.pdf-card-nm{font-size:11px;font-weight:700;color:#0F172A;}
.pdf-card-sz{font-size:9.5px;color:#64748B;margin-top:1px;}

.footer{margin-top:14px;padding-top:8px;border-top:1px solid #e5e9f2;text-align:center;font-size:9px;color:#94A3B8;}
@page{size:A4 portrait;margin:0;}
@media print{
  body{background:#fff;padding:0;}
  .page{width:auto;min-height:auto;margin:0;padding:14mm;box-shadow:none;}
  .entry{page-break-inside:avoid;}
  .attach-card{page-break-inside:avoid;}
  -webkit-print-color-adjust:exact;
  print-color-adjust:exact;
}
/* Colorless Report — strips gradients / colored backgrounds / colored
   tag fills to dark-on-white with light gray borders. Activates only
   when .acc-bw is present on the body. */
.acc-bw .head{border-bottom-color:#0F172A !important;border-bottom-width:1.5px !important;}
.acc-bw .logo{background:#FFFFFF !important;color:#0F172A !important;border:1px solid #0F172A !important;}
.acc-bw .title{color:#0F172A !important;}
.acc-bw .summary-card{background:#FFFFFF !important;border-color:#D1D5DB !important;}
.acc-bw .summary-card .v[style*="color"]{color:#0F172A !important;}
.acc-bw .summary-stat-ic{background:#FFFFFF !important;color:#0F172A !important;border:1px solid #0F172A !important;}
.acc-bw .stat-pill{background:transparent !important;color:#0F172A !important;border-color:#9CA3AF !important;}
.acc-bw .entry{background:#FFFFFF !important;border-color:#D1D5DB !important;}
.acc-bw .entry-tag{background:transparent !important;color:#0F172A !important;border-color:#9CA3AF !important;}
.acc-bw .entry-amt[style*="color"]{color:#0F172A !important;}
.acc-bw .pdf-card{background:transparent !important;border-color:#9CA3AF !important;}
.acc-bw .pdf-card-ic{background:#0F172A !important;}
.acc-bw .attach-card{border-color:#D1D5DB !important;}
.acc-bw .sec-band{background:#FFFFFF !important;color:#0F172A !important;border:1.5px solid #0F172A !important;}
</style></head><body${isBW ? ' class="acc-bw"' : ''}>
<div class="page">

<div class="head">
  <div class="logo">${logoHtml}</div>
  <div>
    <div class="school">${escH(school?.name || 'School')}</div>
    <div class="title">Account Book Ledger Report</div>
    ${school?.address ? `<div class="addr">${escH(school.address)}</div>` : ''}
    ${school?.session ? `<div class="session">Academic Session: ${escH(school.session)}</div>` : ''}
  </div>
  <div class="meta">Generated: ${today}<br/>Period: ${escH(book.openDate)} → ${accFmtDate(c.lastDate)}<br/>Entries: ${book.txns.length}</div>
</div>

<div class="book-card">
  <div class="book-card-head">
    <div class="book-card-ic">📒</div>
    <div style="flex:1;min-width:0">
      <div class="book-card-name">${escH(book.name)}</div>
      <div class="book-card-party">${escH(book.party || '—')} · ${book.type === 'payable' ? 'Payable (school owes party)' : 'Receivable (party owes school)'}</div>
    </div>
    <span class="status-pill">${escH(book.status || 'active')}</span>
  </div>
  ${book.desc ? `<div class="book-card-desc">${escH(book.desc)}</div>` : ''}
</div>

<div class="kpi-row">
  <div class="kpi opening">
    <div class="l">Opening Amount</div>
    <div class="v">Rs. ${(book.opening || 0).toLocaleString('en-PK')}</div>
    <div class="m">${escH(book.openDate)} · by ${escH(book.createdBy || '—')}</div>
  </div>
  <div class="kpi balance">
    <div class="l">Current Balance</div>
    <div class="v purple">Rs. ${c.balance.toLocaleString('en-PK')}</div>
    <div class="m">${book.type === 'payable' ? 'payable to party' : 'receivable'}</div>
  </div>
  <div class="kpi received">
    <div class="l">Total Received</div>
    <div class="v green">Rs. ${c.totalIn.toLocaleString('en-PK')}</div>
    <div class="m">opening + further</div>
  </div>
  <div class="kpi returned">
    <div class="l">Total Returned</div>
    <div class="v red">Rs. ${c.returnedAll.toLocaleString('en-PK')}</div>
    <div class="m">paid back</div>
  </div>
  <div class="kpi cash">
    <div class="l">Cash In Hand</div>
    <div class="v">${book.includeInCash ? 'Included' : 'Excluded'}</div>
    <div class="m">${book.includeInCash ? 'affects cash only' : 'not in cash calc'}</div>
  </div>
  <div class="kpi date">
    <div class="l">Last Transaction</div>
    <div class="v">${accFmtDate(c.lastDate)}</div>
    <div class="m">${book.txns.length} entries total</div>
  </div>
</div>

${book.includeInCash ? `<div class="cash-info">💰 <b>Cash In Hand flag is ON.</b> This book's balance is included in the school's Cash In Hand calculation only — it does not affect Profit &amp; Loss or appear as revenue.</div>` : ''}

<div class="sec-band">
  <span>Transaction Ledger</span>
  <small>${sorted.length} entries · sorted oldest → newest</small>
</div>

${sorted.length === 0
  ? '<div style="text-align:center;color:#94A3B8;padding:30px;border:1px dashed #cbd5e1;border-radius:8px">No transactions recorded yet.</div>'
  : sorted.map(entryBlock).join('')}

<div class="footer">Computer generated report — ${escH(school?.name || 'School')} · ${escH(book.name)} · ${today}</div>

</div><!-- /.page -->
</body></html>`;
}

/* ─── Book Edit Modal (Create / Edit Account Book) ─── */
function BookEditModal({ cfg, currentUser, onClose, onSave, toast }) {
  const [name, setName]               = useState('');
  const [party, setParty]             = useState('');
  const [desc, setDesc]               = useState('');
  const [type, setType]               = useState('payable');
  const [opening, setOpening]         = useState('');
  const [openDate, setOpenDate]       = useState('');
  const [openedBy, setOpenedBy]       = useState('');
  const [includeInCash, setInclude]   = useState(false);

  /* The real logged-in user — shown (disabled) as "Opened By"; their id is
     sent as createdBy / modifiedBy by accountsService.saveAccBook. */
  const loginUserName = sessionStorage.getItem('displayName') || sessionStorage.getItem('userName') || currentUser || '';

  useEffect(() => {
    if (!cfg) return;
    if (cfg.mode === 'edit' && cfg.book) {
      const b = cfg.book;
      setName(b.name); setParty(b.party || ''); setDesc(b.desc || '');
      setType(b.type); setOpening(String(b.opening || 0));
      setOpenDate(b.openDate); setOpenedBy(b.createdBy || loginUserName);
      setInclude(!!b.includeInCash);
    } else {
      setName(''); setParty(''); setDesc('');
      setType('payable'); setOpening('');
      setOpenDate(new Date().toISOString().slice(0, 10));
      setOpenedBy(loginUserName); setInclude(false);
    }
  }, [cfg, currentUser, loginUserName]);

  useEffect(() => {
    if (!cfg) return undefined;
    const onKey = e => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', onKey);
    document.body.style.overflow = 'hidden';
    return () => {
      window.removeEventListener('keydown', onKey);
      document.body.style.overflow = '';
    };
  }, [cfg, onClose]);

  if (!cfg) return null;
  const isEdit = cfg.mode === 'edit';

  const handle = () => {
    if (!name.trim()) { toast('Book title is required', 'error'); return; }
    if (!openDate)    { toast('Opening date is required', 'error'); return; }
    if (opening === '' || Number.isNaN(Number(opening))) { toast('Opening amount is required', 'error'); return; }
    onSave({
      // bookID 0 → insert; existing id → update
      bookID: isEdit ? (cfg.book.bookID || cfg.book.id || 0) : 0,
      name: name.trim(), party: party.trim(), desc: desc.trim(),
      type, opening: Number(opening), openDate, createdBy: openedBy, includeInCash,
    });
  };

  return createPortal(
    <div className="fee-overlay open" onClick={e => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="fee-modal">
        <div className="fee-modal-head">
          <div className="fee-modal-head-title">
            <div className="fee-modal-head-icon" style={{ background: 'linear-gradient(135deg,#7C3AED,#6D28D9)' }}>
              <i className={`fa-solid ${isEdit ? 'fa-pen-to-square' : 'fa-book-medical'}`}></i>
            </div>
            <div>
              <div className="fee-modal-title">{isEdit ? 'Edit Account Book' : 'Create Account Book'}</div>
              <div className="fee-modal-sub">Open a running account for a supplier, vendor, owner or any party</div>
            </div>
          </div>
          <Tooltip text="Close">
            <button className="fee-modal-close" onClick={onClose} aria-label="Close">
              <i className="fa-solid fa-xmark"></i>
            </button>
          </Tooltip>
        </div>
        <div className="fee-modal-body">
          <div className="fee-info acc-info-purple">
            <i className="fa-solid fa-circle-info"></i>
            <span>An Account Book is a running ledger with one party — a <strong>supplier, vendor, contractor, service provider, owner or investor</strong>. The opening amount is the starting balance the school owes (payable) or is owed (receivable).</span>
          </div>
          <div className="acc-form-grid">
            <div className="fee-field-stack">
              <label className="fee-label">Book Title <span className="acc-req">*</span></label>
              <input className="fee-input" value={name} onChange={e => setName(e.target.value)} placeholder="e.g. Crescent Uniforms — Supplier" autoFocus />
            </div>
            <div className="fee-field-stack">
              <label className="fee-label">Party / Counterparty</label>
              <input className="fee-input" value={party} onChange={e => setParty(e.target.value)} placeholder="Supplier, vendor or person name" />
            </div>
          </div>
          <div className="fee-field-stack" style={{ marginTop: 4 }}>
            <label className="fee-label">Description</label>
            <textarea className="fee-input fee-textarea" value={desc} onChange={e => setDesc(e.target.value)} rows={3} placeholder="e.g. Uniform supplier — purchases on credit, paid in installments" />
          </div>
          <div className="acc-form-grid">
            <div className="fee-field-stack">
              <label className="fee-label">Book Type</label>
              <div className="fee-select-wrap">
                <select className="fee-select" value={type} onChange={e => setType(e.target.value)}>
                  <option value="payable">Payable — the school owes this party</option>
                  <option value="receivable">Receivable — this party owes the school</option>
                </select>
                <i className="fa-solid fa-chevron-down"></i>
              </div>
            </div>
            <div className="fee-field-stack">
              <label className="fee-label">Opening Date <span className="acc-req">*</span></label>
              <input className="fee-input" type="date" value={openDate} onChange={e => setOpenDate(e.target.value)} />
            </div>
          </div>
          <div className="acc-form-grid">
            <div className="fee-field-stack">
              <label className="fee-label">Opening Amount <span className="acc-req">*</span></label>
              <input className="fee-input" type="number" value={opening} onChange={e => setOpening(e.target.value)} placeholder="e.g. 0 if starting fresh" />
            </div>
            <div className="fee-field-stack">
              <label className="fee-label">Opened By</label>
              <input className="fee-input" value={openedBy} disabled readOnly />
            </div>
          </div>

          {/* <button type="button" className="acc-cash-toggle" onClick={() => setInclude(v => !v)}>
            <div className={`acc-cash-toggle-sw${includeInCash ? ' on' : ''}`}><span /></div>
            <div className="acc-cash-toggle-text">
              <div className="acc-cash-toggle-title"><i className="fa-solid fa-wallet"></i> Include in Cash In Hand</div>
              <div className="acc-cash-toggle-desc">
                Turn on if the school physically holds this cash.{' '}
                <strong>This only affects Cash In Hand calculations — it will not impact Profit &amp; Loss or appear as revenue.</strong>
              </div>
            </div>
          </button> */}
        </div>
        <div className="fee-modal-foot">
          <button className="fee-btn fee-btn-ghost" onClick={onClose}>Cancel</button>
          <button className="fee-btn fee-btn-primary" onClick={handle}>
            <i className="fa-solid fa-floppy-disk"></i> {isEdit ? 'Save Changes' : 'Create Book'}
          </button>
        </div>
      </div>
    </div>,
    document.body
  );
}

/* ─── Book Txn Modal (Add / Edit ledger entry) ─── */
function BookTxnModal({ cfg, users, currentUser, book, onClose, onSave, toast }) {
  const [type, setType]           = useState('received');
  const [date, setDate]           = useState('');
  const [amount, setAmount]       = useState('');
  const [notes, setNotes]         = useState('');
  const [enteredBy, setEnteredBy] = useState('');
  const [attachments, setAttachments] = useState([]);
  const fileInputRef              = useRef(null);
  const [dragOver, setDragOver]   = useState(false);

  useEffect(() => {
    if (!cfg) return;
    if (cfg.mode === 'edit' && cfg.txn) {
      const t = cfg.txn;
      setType(t.type); setDate(t.date);
      setAmount(String(Math.abs(t.amount))); setNotes(t.notes || '');
      setEnteredBy(t.enteredBy || currentUser);
      setAttachments(Array.isArray(t.attachments) ? [...t.attachments] : []);
    } else {
      setType('received');
      setDate(new Date().toISOString().slice(0, 10));
      setAmount(''); setNotes(''); setEnteredBy(currentUser);
      setAttachments([]);
    }
  }, [cfg, currentUser]);

  useEffect(() => {
    if (!cfg) return undefined;
    const onKey = e => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', onKey);
    document.body.style.overflow = 'hidden';
    return () => {
      window.removeEventListener('keydown', onKey);
      document.body.style.overflow = '';
    };
  }, [cfg, onClose]);

  if (!cfg) return null;
  const isEdit = cfg.mode === 'edit';

  /* Live preview of balance after this txn */
  const c = book ? bookCalc(book) : { balance: 0 };
  const amt = Number(amount) || 0;
  const newBal = c.balance + (type === 'received' ? amt : type === 'returned' ? -amt : amt);

  const handle = () => {
    if (!date)   { toast('Date is required', 'error'); return; }
    if (!amt)    { toast('Amount is required', 'error'); return; }
    onSave({
      id: isEdit ? cfg.txn.id : 0, // 0 → insert; existing record id → update
      type, date, amount: type === 'adjustment' ? Number(amount) : amt,
      notes: notes.trim(), enteredBy, attachments,
    });
  };

  /* Read selected files as { name, size, kind, data:dataURL }. Caps total
     count at 8, single-file size at 5 MB; rejects anything outside
     image/* and application/pdf. */
  const ingestFiles = (files) => {
    const arr = Array.from(files || []);
    if (!arr.length) return;
    if (attachments.length + arr.length > 8) {
      toast('Max 8 attachments per transaction', 'warning');
      return;
    }
    arr.forEach(file => {
      const isImg = (file.type || '').startsWith('image/');
      const isPdf = (file.type || '') === 'application/pdf' || /\.pdf$/i.test(file.name);
      if (!isImg && !isPdf) {
        toast(`Skipped "${file.name}" — only images and PDFs supported`, 'warning');
        return;
      }
      if (file.size > 5 * 1024 * 1024) {
        toast(`Skipped "${file.name}" — exceeds 5 MB limit`, 'warning');
        return;
      }
      const reader = new FileReader();
      reader.onload = () => {
        const att = {
          name: file.name,
          size: file.size < 1024 * 1024
            ? `${Math.max(1, Math.round(file.size / 1024))} KB`
            : `${(file.size / (1024 * 1024)).toFixed(1)} MB`,
          kind: isImg ? 'img' : 'pdf',
          data: reader.result,
          file, // raw File kept for multipart upload (AttachmentFile)
        };
        setAttachments(prev => [...prev, att]);
      };
      reader.onerror = () => toast(`Failed to read "${file.name}"`, 'error');
      reader.readAsDataURL(file);
    });
  };

  const onFileSelect = (e) => {
    ingestFiles(e.target.files);
    /* reset the input so the same file can be re-picked */
    if (fileInputRef.current) fileInputRef.current.value = '';
  };
  const onDrop = (e) => {
    e.preventDefault();
    setDragOver(false);
    ingestFiles(e.dataTransfer.files);
  };
  const removeAttachment = (i) => {
    setAttachments(prev => prev.filter((_, idx) => idx !== i));
  };

    const loginUserName = sessionStorage.getItem('displayName') || sessionStorage.getItem('userName') || currentUser || '';

  return createPortal(
    <div className="fee-overlay open" onClick={e => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="fee-modal lg">
        <div className="fee-modal-head">
          <div className="fee-modal-head-title">
            <div className="fee-modal-head-icon" style={{ background: 'linear-gradient(135deg,#7C3AED,#6D28D9)' }}>
              <i className="fa-solid fa-money-bill-transfer"></i>
            </div>
            <div>
              <div className="fee-modal-title">{isEdit ? 'Edit Transaction' : 'Add Transaction'}</div>
              <div className="fee-modal-sub">Record a movement on this account book</div>
            </div>
          </div>
          <Tooltip text="Close">
            <button className="fee-modal-close" onClick={onClose} aria-label="Close">
              <i className="fa-solid fa-xmark"></i>
            </button>
          </Tooltip>
        </div>
        <div className="fee-modal-body">
          <div className="acc-txntype-seg">
            <button type="button" className={`acc-txntype${type === 'received' ? ' active' : ''}`} onClick={() => setType('received')}>
              <i className="fa-solid fa-arrow-down"></i>
              <span><b>Received / Purchased</b><small>Credit purchase, loan or contribution — balance owed goes up</small></span>
            </button>
            <button type="button" className={`acc-txntype${type === 'returned' ? ' active' : ''}`} onClick={() => setType('returned')}>
              <i className="fa-solid fa-arrow-up"></i>
              <span><b>Paid / Returned</b><small>Payment made to the party — balance goes down</small></span>
            </button>
            {/* <button type="button" className={`acc-txntype${type === 'adjustment' ? ' active' : ''}`} onClick={() => setType('adjustment')}>
              <i className="fa-solid fa-sliders"></i>
              <span><b>Adjustment</b><small>Discount / write-off / correction</small></span>
            </button> */}
          </div>

          <div className="acc-entry-grid acc-entry-grid--2" style={{ marginTop: 18 }}>
            <div className="fee-field-stack">
              <label className="fee-label">Date <span className="acc-req">*</span></label>
              <input className="fee-input" type="date" value={date} onChange={e => setDate(e.target.value)} />
            </div>
            <div className="fee-field-stack">
              <label className="fee-label">Amount <span className="acc-req">*</span></label>
              <input className="fee-input" type="number" value={amount} onChange={e => setAmount(e.target.value)} placeholder="Enter amount" />
            </div>
          </div>
          <div className="acc-entry-grid acc-entry-grid--2">
            <div className="fee-field-stack">
              <label className="fee-label">Notes / Description</label>
              <input className="fee-input" value={notes} onChange={e => setNotes(e.target.value)} placeholder="e.g. Part payment to supplier — cheque #44120" />
            </div>
            <div className="fee-field-stack">
              <label className="fee-label">Entered By</label>
              <div className="fee-select-wrap">
                  <input className="fee-input" value={loginUserName} disabled readOnly />
                {/* <select className="fee-select" value={loginUserName} onChange={e => setEnteredBy(e.target.value)}>
                  {/* {users.map(u => <option key={u}>{u}</option>)}
                  {loginUserName}
                </select> */}
                {/* <i className="fa-solid fa-chevron-down"></i> */}
              </div>
            </div>
          </div>

          {/* Attachment uploader */}
          <div
            className={`acc-attach-zone${dragOver ? ' drag' : ''}`}
            onClick={() => fileInputRef.current?.click()}
            onDragOver={e => { e.preventDefault(); setDragOver(true); }}
            onDragLeave={() => setDragOver(false)}
            onDrop={onDrop}
            role="button"
            tabIndex={0}
            onKeyDown={e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); fileInputRef.current?.click(); } }}
          >
            <input
              ref={fileInputRef}
              type="file"
              multiple
              accept="image/*,.pdf,application/pdf"
              style={{ display: 'none' }}
              onChange={onFileSelect}
            />
            <i className="fa-solid fa-cloud-arrow-up"></i>
            <div className="acc-attach-zone-t">Attach receipts, cheque images or payment proofs</div>
            <div className="acc-attach-zone-s">Click or drag &amp; drop — images &amp; PDFs (max 5 MB each, up to 8 files)</div>
          </div>
          {attachments.length > 0 && (
            <div className="acc-attach-list">
              {attachments.map((a, i) => (
                <div key={i} className="acc-attach-chip">
                  <div className={`acc-attach-chip-ic ${a.kind || 'img'}`}>
                    <i className={`fa-solid ${a.kind === 'pdf' ? 'fa-file-pdf' : 'fa-image'}`}></i>
                  </div>
                  <div style={{ minWidth: 0, flex: 1 }}>
                    <div className="acc-attach-chip-nm" title={a.name}>{a.name}</div>
                    <div className="acc-attach-chip-sz">{a.size}</div>
                  </div>
                  <Tooltip text="Remove attachment">
                    <button type="button" className="acc-attach-chip-x" onClick={e => { e.stopPropagation(); removeAttachment(i); }}>
                      <i className="fa-solid fa-xmark"></i>
                    </button>
                  </Tooltip>
                </div>
              ))}
            </div>
          )}

          {book && amt > 0 && !isEdit && (
            <div className="acc-book-runpreview">
              <div className="acc-book-runpreview-row">
                <span>Current Balance</span>
                <b>{fmtMoney(c.balance)}</b>
              </div>
              <div className="acc-book-runpreview-row">
                <span>This Entry</span>
                <b className={type === 'received' ? 'in' : type === 'returned' ? 'out' : 'adj'}>
                  {type === 'returned' ? '−' : type === 'adjustment' && amt < 0 ? '−' : '+'}{fmtMoney(Math.abs(amt))}
                </b>
              </div>
              <div className="acc-book-runpreview-row total">
                <span>Balance After</span>
                {/* Preview bhi minus dikhata hai — warna user ko lagta hai entry
                    ke baad balance 0 hoga, jab ke asal me wo minus me jayega. */}
                <b style={newBal < 0 ? { color: '#DC2626' } : undefined}>{fmtMoney(newBal)}</b>
              </div>
            </div>
          )}
        </div>
        <div className="fee-modal-foot">
          <button className="fee-btn fee-btn-ghost" onClick={onClose}>Cancel</button>
          <button className="fee-btn fee-btn-primary" onClick={handle}>
            <i className="fa-solid fa-floppy-disk"></i> {isEdit ? 'Save Changes' : 'Save Transaction'}
          </button>
        </div>
      </div>
    </div>,
    document.body
  );
}

